// Êxodo — tradução dos originais (versificação: Nova Vulgata)
// Formato: {s:"subtítulo"} abre trecho; {v,t,n} prosa; {v,l:[...]} verso;
// np:1 marca início de parágrafo.
// =====================================================================

window.TEXTOS_SEED["exodo"][1] = [
{s:"Os israelitas oprimidos no Egito"},
{v:1,t:"Estes são os nomes dos filhos de Israel que foram para o Egito com Jacó, cada um com a sua família:",n:"O Êxodo retoma a história onde o Gênesis a deixou (Gênesis 46,8–27; 50,26). A família de setenta pessoas vai se tornar um povo, e o povo escravizado vai conhecer o nome do seu Deus."},
{v:2,t:"Rúben, Simeão, Levi e Judá,"},
{v:3,t:"Issacar, Zabulon e Benjamim,"},
{v:4,t:"Dã e Neftali, Gad e Aser."},
{v:5,t:"Os descendentes de Jacó eram, ao todo, setenta pessoas; José já estava no Egito."},
{v:6,t:"José morreu, e também todos os seus irmãos e toda aquela geração;"},
{v:7,t:"mas os filhos de Israel foram fecundos, multiplicaram-se, cresceram e se tornaram muito poderosos, e a terra ficou cheia deles.",n:"Eco da bênção da criação: sede fecundos, multiplicai-vos e enchei a terra (Gênesis 1,28)."},
{v:8,t:"Subiu ao trono do Egito um novo rei, que não tinha conhecido José.",np:1},
{v:9,t:"Ele disse ao seu povo: Vede: o povo dos filhos de Israel é mais numeroso e mais forte do que nós."},
{v:10,t:"Vamos agir com astúcia contra ele, para que não se multiplique mais; do contrário, em caso de guerra, pode aliar-se aos nossos inimigos, combater contra nós e sair do país.",np:1},
{v:11,t:"Puseram sobre eles capatazes, para oprimi-los com trabalhos forçados; e eles construíram para o faraó as cidades-armazéns de Pitom e Ramessés.",n:"Ramessés: provavelmente a cidade de Ramsés II, no século XIII antes de Cristo, o faraó sob o qual muitos situam o Êxodo."},
{v:12,t:"Mas, quanto mais os oprimiam, tanto mais eles se multiplicavam e cresciam.",np:1},
{v:13,t:"Os egípcios passaram a ter medo dos filhos de Israel e os reduziram à escravidão"},
{v:14,t:"e lhes amarguravam a vida com trabalhos pesados de barro e de tijolos e com toda espécie de trabalhos no campo, a que os obrigavam com dureza."},
{v:15,t:"O rei do Egito falou também às parteiras dos hebreus, uma das quais se chamava Sefra, e a outra Fua,",np:1},
{v:16,t:"e lhes ordenou: Quando assistirdes as mulheres hebreias no parto, observai: se for menino, matai-o; se for menina, deixai-a viver."},
{v:17,t:"Mas as parteiras temiam a Deus e não fizeram o que o rei do Egito lhes tinha ordenado: deixavam viver os meninos.",n:"Primeira desobediência civil da Bíblia: duas mulheres, cujos nomes o texto guarda, enquanto o faraó fica sem nome."},
{v:18,t:"O rei do Egito chamou as parteiras e lhes disse: Por que fizestes isso, deixando viver os meninos?"},
{v:19,t:"As parteiras responderam ao faraó: As mulheres hebreias não são como as egípcias: são robustas e dão à luz antes que a parteira chegue.",np:1},
{v:20,t:"Deus fez bem às parteiras; e o povo se multiplicou e se tornou muito forte."},
{v:21,t:"E, porque as parteiras temeram a Deus, ele lhes deu uma família."},
{v:22,t:"Então o faraó deu esta ordem a todo o seu povo: Todo menino que nascer, lançai-o ao Rio; mas deixai viver todas as meninas.",np:1,n:"O Rio: o Nilo. Mateus verá um eco deste relato na matança dos inocentes por Herodes (Mateus 2,16)."}
];

window.TEXTOS_SEED["exodo"][2] = [
{s:"O nascimento de Moisés"},
{v:1,t:"Um homem da casa de Levi foi tomar por mulher uma filha de Levi."},
{v:2,t:"Ela concebeu e deu à luz um filho; e, vendo que era bonito, escondeu-o durante três meses."},
{v:3,t:"Quando não pôde mais escondê-lo, tomou um cesto de papiro, vedou-o com betume e piche, pôs dentro o menino e o colocou entre os juncos, à beira do Rio,",np:1,n:"Cesto: a mesma palavra hebraica da arca de Noé (Gênesis 6,14); outra vez uma caixa vedada com betume salva a vida sobre as águas."},
{v:4,t:"enquanto a irmã do menino ficava de longe, para ver o que lhe aconteceria."},
{v:5,t:"Nisso a filha do faraó desceu para se banhar no Rio, enquanto as suas criadas andavam pela margem. Ela viu o cesto no meio do juncal e mandou uma das suas servas buscá-lo.",np:1},
{v:6,t:"Abriu-o e viu a criança: era um menino que chorava. Teve pena dele e disse: É um dos filhos dos hebreus."},
{v:7,t:"A irmã do menino disse à filha do faraó: Queres que eu vá chamar uma ama entre as mulheres hebreias, para que te amamente o menino?"},
{v:8,t:"A filha do faraó respondeu: Vai. E a moça foi chamar a mãe do menino."},
{v:9,t:"A filha do faraó lhe disse: Leva este menino e amamenta-o para mim; eu te pagarei o teu salário. A mulher tomou o menino e o amamentou; e, quando ele cresceu, levou-o à filha do faraó."},
{v:10,t:"Ela o adotou como filho e lhe deu o nome de Moisés, dizendo: Eu o tirei das águas.",n:"Moisés é um nome egípcio, que significa filho, como em Ramsés, filho de Rá; o texto o aproxima do verbo hebraico mashah, tirar das águas."},
{s:"Moisés foge para Madiã"},
{v:11,t:"Naqueles dias, quando Moisés já era adulto, saiu para ver os seus irmãos e viu os trabalhos pesados que faziam; viu também um egípcio que batia num hebreu, um dos seus irmãos."},
{v:12,t:"Olhou para um lado e para o outro e, vendo que não havia ninguém, matou o egípcio e o escondeu na areia.",n:"Nota do tradutor: o narrador não aprova nem condena o gesto de Moisés; o texto não foi suavizado. Estêvão o interpreta como uma primeira tentativa, incompreendida, de libertar os irmãos (Atos 7,23–29)."},
{v:13,t:"No dia seguinte, saiu de novo e viu dois hebreus brigando; e disse ao que estava errado: Por que bates no teu companheiro?"},
{v:14,t:"Ele respondeu: Quem te constituiu chefe e juiz sobre nós? Queres matar-me, como mataste o egípcio? Moisés ficou com medo e pensou: Com certeza o caso se tornou conhecido."},
{v:15,t:"O faraó soube do caso e procurou matar Moisés. Moisés fugiu da presença do faraó e foi morar na terra de Madiã; chegando à terra de Madiã, sentou-se junto a um poço.",np:1},
{v:16,t:"O sacerdote de Madiã tinha sete filhas, que vieram tirar água e encheram os bebedouros para dar de beber ao rebanho de seu pai."},
{v:17,t:"Chegaram uns pastores e as expulsaram; mas Moisés se levantou, defendeu as moças e deu de beber ao rebanho delas.",np:1,n:"Encontro junto a um poço, como o do servo de Abraão com Rebeca (Gênesis 24) e o de Jacó com Raquel (Gênesis 29): o leitor já sabe como a história termina."},
{v:18,t:"Quando voltaram para junto de Raguel, seu pai, ele lhes perguntou: Por que voltastes hoje tão cedo?",n:"Raguel: o sogro de Moisés é chamado também Jetro (3,1) e Hobab (Juízes 4,11; compare Números 10,29): tradições diferentes."},
{v:19,t:"Responderam: Um egípcio nos defendeu dos pastores; e ainda tirou água para nós e deu de beber ao rebanho."},
{v:20,t:"Ele disse às filhas: E onde está ele? Por que deixastes ir embora esse homem? Chamai-o para comer conosco."},
{v:21,t:"Moisés aceitou morar com aquele homem, que lhe deu por mulher sua filha Séfora."},
{v:22,t:"Ela deu à luz um filho, a quem Moisés chamou Gersam, porque dizia: Sou um estrangeiro em terra estranha.",n:"Gersam soa em hebraico como estrangeiro ali."},
{s:"Deus ouve o clamor do seu povo"},
{v:23,t:"Muito tempo depois, o rei do Egito morreu. Os filhos de Israel gemiam por causa da escravidão e clamavam; e do fundo da sua escravidão o seu clamor subiu até Deus."},
{v:24,t:"Deus ouviu os seus gemidos e se lembrou da sua aliança com Abraão, com Isaac e com Jacó."},
{v:25,t:"O Senhor olhou para os filhos de Israel e se manifestou a eles.",n:"E se manifestou a eles: assim a Nova Vulgata, com a tradução grega; o hebraico diz: e Deus tomou conhecimento."}
];

window.TEXTOS_SEED["exodo"][3] = [
{s:"A sarça ardente"},
{v:1,t:"Moisés apascentava o rebanho de Jetro, seu sogro, sacerdote de Madiã. Levou o rebanho para além do deserto e chegou ao Horeb, a montanha de Deus.",n:"O Horeb é outro nome do Sinai, o monte da aliança."},
{v:2,t:"O anjo do Senhor lhe apareceu numa chama de fogo, do meio de uma sarça. Moisés olhou: a sarça ardia no fogo, mas não se consumia."},
{v:3,t:"Moisés disse: Vou aproximar-me para ver este grande espetáculo: por que a sarça não se consome?",np:1},
{v:4,t:"O Senhor viu que ele se aproximava para ver; e Deus o chamou do meio da sarça: Moisés, Moisés! Ele respondeu: Aqui estou."},
{v:5,t:"Deus disse: Não te aproximes daqui; tira as sandálias dos pés, porque o lugar onde estás é terra santa."},
{v:6,t:"E acrescentou: Eu sou o Deus de teu pai, o Deus de Abraão, o Deus de Isaac e o Deus de Jacó. Moisés cobriu o rosto, porque tinha medo de olhar para Deus.",n:"Jesus cita estas palavras para mostrar que Deus é Deus dos vivos (Marcos 12,26–27)."},
{v:7,t:"O Senhor disse: Eu vi a aflição do meu povo no Egito e ouvi o seu clamor por causa da dureza dos seus opressores.",np:1},
{v:8,t:"Conheço os seus sofrimentos; por isso desci para libertá-lo das mãos dos egípcios e fazê-lo subir daquela terra para uma terra boa e espaçosa, uma terra onde corre leite e mel, o território dos cananeus, dos heteus, dos amorreus, dos ferezeus, dos heveus e dos jebuseus.",n:"Terra onde corre leite e mel: imagem de fartura para pastores, que viviam do rebanho e do mel silvestre."},
{v:9,t:"Agora, o clamor dos filhos de Israel chegou até mim, e eu vi a opressão com que os egípcios os oprimem;"},
{v:10,t:"vai, pois; eu te envio ao faraó, para que tires do Egito o meu povo, os filhos de Israel."},
{v:11,t:"Moisés disse a Deus: Quem sou eu para ir ao faraó e tirar do Egito os filhos de Israel?"},
{v:12,t:"Deus respondeu: Eu estarei contigo; e este será para ti o sinal de que sou eu que te envio: quando tiveres tirado o povo do Egito, servireis a Deus sobre esta montanha."},
{s:"O nome de Deus"},
{v:13,t:"Moisés disse a Deus: Quando eu for aos filhos de Israel e lhes disser: O Deus de vossos pais me enviou a vós, e eles me perguntarem qual é o seu nome, que lhes direi?"},
{v:14,t:"Deus disse a Moisés: Eu sou aquele que sou. E acrescentou: Assim dirás aos filhos de Israel: Eu Sou me enviou a vós.",n:"Eu sou aquele que sou: assim a Nova Vulgata, com a tradução grega. O hebraico ehyeh asher ehyeh pode querer dizer também eu serei o que serei, ou eu sou aquele que estará convosco (compare 3,12). O nome divino YHWH, que vem do mesmo verbo ser, não era pronunciado pelos judeus por respeito; em seu lugar se dizia Senhor, e é assim que esta tradução o traz."},
{v:15,t:"Deus disse ainda a Moisés: Assim dirás aos filhos de Israel: O Senhor, o Deus de vossos pais, o Deus de Abraão, o Deus de Isaac e o Deus de Jacó, enviou-me a vós. Este é o meu nome para sempre, e assim serei lembrado de geração em geração."},
{v:16,t:"Vai, reúne os anciãos de Israel e dize-lhes: O Senhor, o Deus de vossos pais, o Deus de Abraão, de Isaac e de Jacó, apareceu-me e disse: Eu vos visitei e vi o que vos fazem no Egito;"},
{v:17,t:"e decidi tirar-vos da aflição do Egito e levar-vos para a terra dos cananeus, dos heteus, dos amorreus, dos ferezeus, dos heveus e dos jebuseus, uma terra onde corre leite e mel."},
{v:18,t:"Eles ouvirão a tua voz; e tu irás com os anciãos de Israel ao rei do Egito, e lhe direis: O Senhor, o Deus dos hebreus, veio ao nosso encontro; deixa-nos, pois, ir ao deserto, a três dias de caminho, para oferecer sacrifícios ao Senhor, nosso Deus."},
{v:19,t:"Mas eu sei que o rei do Egito não vos deixará ir, a não ser forçado por uma mão poderosa.",np:1},
{v:20,t:"Por isso estenderei a minha mão e ferirei o Egito com todos os prodígios que farei no meio dele; depois disso, ele vos deixará ir."},
{v:21,t:"Farei que este povo encontre favor aos olhos dos egípcios; e, quando partirdes, não saireis de mãos vazias.",np:1},
{v:22,t:"Cada mulher pedirá à sua vizinha e à hóspede da sua casa objetos de prata e de ouro e roupas; e vós os poreis nos vossos filhos e nas vossas filhas, e assim despojareis os egípcios.",n:"Os escravos não sairão de mãos vazias: é o salário de anos de trabalho forçado (compare Deuteronômio 15,13–14)."}
];

window.TEXTOS_SEED["exodo"][4] = [
{s:"Os sinais dados a Moisés"},
{v:1,t:"Moisés respondeu: E se não acreditarem em mim nem ouvirem a minha voz, e disserem: O Senhor não te apareceu?"},
{v:2,t:"O Senhor lhe perguntou: Que tens na mão? Ele respondeu: Um cajado."},
{v:3,t:"O Senhor disse: Joga-o no chão! Ele o jogou no chão, e o cajado se transformou numa serpente, e Moisés fugiu dela."},
{v:4,t:"O Senhor disse a Moisés: Estende a mão e pega-a pela cauda! Ele estendeu a mão e a pegou, e ela se transformou de novo em cajado na sua mão."},
{v:5,t:"Isto é para que acreditem que te apareceu o Senhor, o Deus de seus pais, o Deus de Abraão, o Deus de Isaac e o Deus de Jacó."},
{v:6,t:"O Senhor lhe disse ainda: Põe a mão no peito! Ele pôs a mão no peito e, quando a tirou, a mão estava leprosa, branca como a neve.",np:1,n:"Leprosa: o termo bíblico designa várias doenças de pele, e não só a lepra propriamente dita."},
{v:7,t:"O Senhor disse: Põe de novo a mão no peito! Ele pôs de novo a mão no peito e, quando a tirou, ela estava como o resto do seu corpo."},
{v:8,t:"Se não acreditarem em ti nem derem atenção ao primeiro sinal, acreditarão no segundo sinal."},
{v:9,t:"E, se não acreditarem nem mesmo nestes dois sinais e não ouvirem a tua voz, tira água do Rio e derrama-a sobre a terra seca, e a água que tirares do Rio se transformará em sangue sobre a terra seca."},
{v:10,t:"Moisés disse ao Senhor: Por favor, meu Senhor, eu não sou homem de palavra fácil, nem de ontem nem de anteontem, nem desde que falaste ao teu servo; tenho a boca pesada e a língua pesada.",np:1},
{v:11,t:"O Senhor lhe disse: Quem deu a boca ao homem? Quem faz o mudo ou o surdo, o que vê ou o cego? Não sou eu, o Senhor?"},
{v:12,t:"Vai, pois; eu estarei na tua boca e te ensinarei o que deves dizer."},
{v:13,t:"Moisés disse: Por favor, meu Senhor, envia quem quiseres enviar."},
{v:14,t:"Então a ira do Senhor se acendeu contra Moisés, e ele disse: Aarão, o levita, é teu irmão: sei que ele fala bem. Ele mesmo está vindo ao teu encontro; e, quando te vir, se alegrará no seu coração."},
{v:15,t:"Falarás com ele e porás as minhas palavras na sua boca; e eu estarei na tua boca e na boca dele e vos ensinarei o que deveis fazer."},
{v:16,t:"Ele falará por ti ao povo: ele será a tua boca, e tu serás para ele como Deus."},
{v:17,t:"Toma também na mão este cajado, com o qual farás os sinais."},
{s:"Moisés volta ao Egito"},
{v:18,t:"Moisés partiu e voltou para junto de Jetro, seu sogro, e lhe disse: Deixa-me ir, por favor, voltar para junto dos meus irmãos no Egito, para ver se ainda estão vivos. Jetro lhe disse: Vai em paz."},
{v:19,t:"O Senhor disse a Moisés em Madiã: Volta para o Egito, porque morreram todos os que procuravam tirar-te a vida."},
{v:20,t:"Moisés tomou a mulher e os filhos, pô-los sobre um jumento e voltou para a terra do Egito; e levava na mão o cajado de Deus."},
{v:21,t:"O Senhor disse a Moisés: Quando voltares ao Egito, faze diante do faraó todos os prodígios que pus na tua mão; mas eu endurecerei o coração dele, e ele não deixará o povo partir.",n:"Nota do tradutor: o texto diz ora que Deus endurece o coração do faraó, ora que o faraó endurece o próprio coração (8,11; 9,34); para o pensamento hebraico, nada escapa ao governo de Deus, sem que o homem deixe de ser responsável. O texto não foi suavizado (compare Romanos 9,17–18)."},
{v:22,t:"Dirás ao faraó: Assim diz o Senhor: Israel é o meu filho primogênito."},
{v:23,t:"Eu te digo: Deixa partir o meu filho, para que me preste culto; se te recusas a deixá-lo partir, eu matarei o teu filho primogênito.",np:1},
{v:24,t:"No caminho, no lugar onde passavam a noite, o Senhor foi ao encontro de Moisés e quis matá-lo.",np:1,n:"Nota do tradutor: um dos trechos mais enigmáticos da Bíblia, e o texto não foi suavizado. O perigo parece ligado à falta de circuncisão do filho de Moisés; Séfora o afasta com um rito de sangue."},
{v:25,t:"Então Séfora tomou uma pedra afiada, cortou o prepúcio do filho, tocou-lhe os pés e disse: Tu és para mim um esposo de sangue."},
{v:26,t:"E o Senhor o deixou. Ela tinha dito esposo de sangue por causa da circuncisão."},
{v:27,t:"O Senhor disse a Aarão: Vai ao deserto, ao encontro de Moisés. Ele foi, encontrou-o na montanha de Deus e o beijou.",np:1},
{v:28,t:"Moisés contou a Aarão todas as palavras que o Senhor lhe tinha mandado dizer e todos os sinais que lhe tinha ordenado fazer."},
{v:29,t:"Moisés e Aarão foram e reuniram todos os anciãos dos filhos de Israel."},
{v:30,t:"Aarão repetiu todas as palavras que o Senhor tinha dito a Moisés e fez os sinais diante do povo."},
{v:31,t:"O povo acreditou; e, quando ouviram que o Senhor tinha visitado os filhos de Israel e visto a sua aflição, inclinaram-se e se prostraram."}
];

window.TEXTOS_SEED["exodo"][5] = [
{s:"Diante do faraó: o trabalho aumenta"},
{v:1,t:"Depois disso, Moisés e Aarão foram ao faraó e disseram: Assim diz o Senhor, o Deus de Israel: Deixa partir o meu povo, para que me ofereça sacrifícios no deserto."},
{v:2,t:"O faraó respondeu: Quem é o Senhor, para que eu ouça a sua voz e deixe Israel partir? Não conheço o Senhor, e não deixarei Israel partir.",n:"Não conheço o Senhor: toda a história das pragas responde a esta frase; o refrão será: sabereis que eu sou o Senhor (7,5.17; 8,18; 14,4)."},
{v:3,t:"Eles disseram: O Deus dos hebreus veio ao nosso encontro; deixa-nos ir ao deserto, a três dias de caminho, para oferecer sacrifícios ao Senhor, nosso Deus, para que ele não nos fira com a peste ou com a espada."},
{v:4,t:"O rei do Egito lhes disse: Moisés e Aarão, por que distraís o povo do seu trabalho? Ide cuidar das vossas tarefas!"},
{v:5,t:"E o faraó acrescentou: Esse povo já é numeroso demais no país, e vós ainda quereis dar-lhe descanso das suas tarefas?"},
{v:6,t:"Naquele mesmo dia, o faraó deu esta ordem aos capatazes do povo e aos seus inspetores:",np:1},
{v:7,t:"Não deis mais palha ao povo para fazer tijolos, como antes; que eles mesmos vão juntar palha."},
{v:8,t:"Mas exigi deles a mesma quantidade de tijolos que faziam antes, sem diminuir nada; são uns preguiçosos, e é por isso que gritam: Vamos oferecer sacrifícios ao nosso Deus."},
{v:9,t:"Que o trabalho pese sobre esses homens e que se ocupem dele, e não deem ouvidos a palavras mentirosas."},
{v:10,t:"Os capatazes do povo e os seus inspetores saíram e disseram ao povo: Assim diz o faraó: Não vos darei mais palha.",np:1},
{v:11,t:"Ide vós mesmos buscar palha onde a encontrardes; mas nada será diminuído do vosso trabalho."},
{v:12,t:"O povo se espalhou por toda a terra do Egito para juntar restolho em lugar de palha."},
{v:13,t:"Os capatazes os pressionavam, dizendo: Completai o vosso trabalho de cada dia, como quando havia palha."},
{v:14,t:"E os inspetores dos filhos de Israel, que os capatazes do faraó tinham posto sobre eles, foram espancados, e lhes diziam: Por que não completastes, nem ontem nem hoje, a vossa quantidade de tijolos, como antes?"},
{v:15,t:"Os inspetores dos filhos de Israel foram queixar-se ao faraó, dizendo: Por que tratas assim os teus servos?",np:1},
{v:16,t:"Não se dá palha aos teus servos, e nos dizem: Fazei tijolos! E eis que os teus servos são espancados, e a culpa é do teu povo."},
{v:17,t:"Ele respondeu: Preguiçosos! Sois uns preguiçosos! Por isso dizeis: Vamos oferecer sacrifícios ao Senhor."},
{v:18,t:"Ide agora trabalhar! Não vos será dada palha, e entregareis a mesma quantidade de tijolos."},
{v:19,t:"Os inspetores dos filhos de Israel viram-se em apuros, porque lhes diziam: Não diminuireis nada da quantidade diária de tijolos.",np:1},
{v:20,t:"Ao saírem da presença do faraó, encontraram Moisés e Aarão, que os esperavam,"},
{v:21,t:"e lhes disseram: Que o Senhor vos veja e vos julgue! Vós nos tornastes odiosos ao faraó e aos seus servos, e pusestes na mão deles a espada para nos matar."},
{v:22,t:"Moisés voltou-se para o Senhor e disse: Senhor, por que maltratas este povo? Para que me enviaste?",n:"A primeira oração de Moisés é uma queixa: como os profetas e os salmistas, ele fala com Deus sem disfarçar a revolta."},
{v:23,t:"Desde que fui ao faraó para falar em teu nome, ele maltrata este povo, e tu não libertaste o teu povo."}
];

window.TEXTOS_SEED["exodo"][6] = [
{s:"O Senhor renova a promessa"},
{v:1,t:"O Senhor respondeu a Moisés: Agora verás o que vou fazer ao faraó: forçado por uma mão poderosa, ele os deixará partir; forçado por uma mão poderosa, ele os expulsará da sua terra."},
{v:2,t:"O Senhor falou a Moisés e lhe disse: Eu sou o Senhor,",np:1},
{v:3,t:"que apareci a Abraão, a Isaac e a Jacó como o Deus Todo-Poderoso; mas não lhes dei a conhecer o meu nome, Senhor.",n:"O Deus Todo-Poderoso: em hebraico, El Shaddai. O narrador sabe que o nome divino já aparece no Gênesis; quer dizer que só agora Deus revela o seu sentido, na libertação do povo."},
{v:4,t:"Também fiz com eles a minha aliança, para lhes dar a terra de Canaã, a terra em que moravam como estrangeiros."},
{v:5,t:"Eu ouvi os gemidos dos filhos de Israel, a quem os egípcios escravizam, e me lembrei da minha aliança."},
{v:6,t:"Por isso dize aos filhos de Israel: Eu sou o Senhor; eu vos tirarei dos trabalhos forçados dos egípcios, vos livrarei da escravidão e vos resgatarei com braço estendido e com grandes julgamentos."},
{v:7,t:"Eu vos tomarei como meu povo e serei o vosso Deus; e sabereis que eu sou o Senhor, vosso Deus, que vos tira dos trabalhos forçados do Egito"},
{v:8,t:"e vos leva à terra que jurei, de mão levantada, dar a Abraão, a Isaac e a Jacó; eu a darei a vós como propriedade, eu, o Senhor."},
{v:9,t:"Moisés falou assim aos filhos de Israel, mas eles não o ouviram, por causa do desânimo e da dureza da escravidão.",np:1},
{v:10,t:"O Senhor disse a Moisés:"},
{v:11,t:"Vai dizer ao faraó, rei do Egito, que deixe os filhos de Israel saírem da sua terra."},
{v:12,t:"Moisés respondeu diante do Senhor: Se os filhos de Israel não me ouvem, como o faraó me ouvirá, a mim, que tenho os lábios incircuncisos?",n:"Lábios incircuncisos: palavra difícil, que não sabe falar (compare 4,10)."},
{v:13,t:"Mas o Senhor falou a Moisés e a Aarão e lhes deu ordens para os filhos de Israel e para o faraó, rei do Egito, a fim de que tirassem do Egito os filhos de Israel.",np:1},
{s:"A genealogia de Moisés e de Aarão"},
{v:14,t:"Estes são os chefes das suas famílias. Filhos de Rúben, primogênito de Israel: Henoc, Falu, Hesron e Carmi; são os clãs de Rúben.",n:"A genealogia interrompe o relato para situar Moisés e Aarão na tribo de Levi; por isso só as três primeiras tribos são mencionadas."},
{v:15,t:"Filhos de Simeão: Jamuel, Jamin, Aod, Jaquin, Soar e Saul, filho da cananeia; são os clãs de Simeão.",np:1},
{v:16,t:"Estes são os nomes dos filhos de Levi, segundo os seus clãs: Gérson, Caat e Merari. Levi viveu cento e trinta e sete anos.",np:1},
{v:17,t:"Filhos de Gérson: Lobni e Semei, segundo os seus clãs.",np:1},
{v:18,t:"Filhos de Caat: Amram, Isaar, Hebron e Oziel. Caat viveu cento e trinta e três anos.",np:1},
{v:19,t:"Filhos de Merari: Mooli e Musi. São estes os clãs de Levi, segundo as suas famílias.",np:1},
{v:20,t:"Amram tomou por mulher Jocabed, sua tia, que lhe deu Aarão e Moisés. Amram viveu cento e trinta e sete anos.",np:1,n:"Casar com a tia seria proibido pela lei posterior (Levítico 18,12): o texto conserva uma tradição antiga sem corrigi-la."},
{v:21,t:"Filhos de Isaar: Coré, Nafeg e Zecri.",np:1},
{v:22,t:"Filhos de Oziel: Misael, Elisafã e Setri.",np:1},
{v:23,t:"Aarão tomou por mulher Eliseba, filha de Aminadab e irmã de Naasson, que lhe deu Nadab, Abiú, Eleazar e Itamar.",np:1},
{v:24,t:"Filhos de Coré: Asir, Elcana e Abiasaf; são os clãs dos coreítas.",np:1},
{v:25,t:"Eleazar, filho de Aarão, tomou por mulher uma das filhas de Putiel, que lhe deu Fineias. São estes os chefes das famílias levíticas, segundo os seus clãs.",np:1},
{v:26,t:"São estes o Aarão e o Moisés a quem o Senhor disse: Tirai do Egito os filhos de Israel, organizados em exércitos.",np:1},
{v:27,t:"Foram eles que falaram ao faraó, rei do Egito, para tirar do Egito os filhos de Israel; são estes Moisés e Aarão,"},
{v:28,t:"do dia em que o Senhor falou a Moisés na terra do Egito."},
{v:29,t:"O Senhor disse a Moisés: Eu sou o Senhor; dize ao faraó, rei do Egito, tudo o que eu te digo.",np:1},
{v:30,t:"Moisés respondeu diante do Senhor: Eu tenho os lábios incircuncisos; como o faraó me ouvirá?"}
];

window.TEXTOS_SEED["exodo"][7] = [
{s:"Moisés e Aarão diante do faraó"},
{v:1,t:"O Senhor disse a Moisés: Olha, eu te constituí como um deus para o faraó, e Aarão, teu irmão, será o teu profeta."},
{v:2,t:"Tu dirás tudo o que eu te ordenar, e Aarão, teu irmão, falará ao faraó, para que deixe os filhos de Israel saírem da sua terra."},
{v:3,t:"Mas eu endurecerei o coração do faraó e multiplicarei os meus sinais e os meus prodígios na terra do Egito."},
{v:4,t:"O faraó não vos ouvirá; então porei a minha mão sobre o Egito e tirarei da terra do Egito os meus exércitos, o meu povo, os filhos de Israel, com grandes julgamentos.",np:1},
{v:5,t:"E os egípcios saberão que eu sou o Senhor, quando eu estender a minha mão sobre o Egito e tirar do meio deles os filhos de Israel."},
{v:6,t:"Moisés e Aarão fizeram como o Senhor lhes tinha ordenado; assim fizeram.",np:1},
{v:7,t:"Moisés tinha oitenta anos, e Aarão, oitenta e três, quando falaram ao faraó."},
{s:"O cajado transformado em serpente"},
{v:8,t:"O Senhor disse a Moisés e a Aarão:"},
{v:9,t:"Quando o faraó vos pedir que façais um prodígio, dirás a Aarão: Toma o teu cajado e joga-o diante do faraó, e ele se transformará numa serpente."},
{v:10,t:"Moisés e Aarão foram ao faraó e fizeram como o Senhor tinha ordenado: Aarão jogou o cajado diante do faraó e dos seus servos, e o cajado se transformou numa serpente."},
{v:11,t:"Mas o faraó chamou os sábios e os feiticeiros; e também os magos do Egito fizeram o mesmo com os seus encantamentos:",np:1,n:"A tradição judaica conservou os nomes de dois desses magos, Janes e Jambres (2 Timóteo 3,8)."},
{v:12,t:"cada um jogou o seu cajado, e os cajados se transformaram em serpentes; mas o cajado de Aarão engoliu os cajados deles."},
{v:13,t:"Contudo, o coração do faraó se endureceu, e ele não os ouviu, como o Senhor tinha dito.",np:1},
{s:"Primeira praga: a água transformada em sangue"},
{v:14,t:"O Senhor disse a Moisés: O coração do faraó está obstinado: ele se recusa a deixar o povo partir.",n:"As pragas atingem as forças que o Egito venerava como divinas, a começar pelo Nilo: o Senhor se mostra senhor da natureza e da história."},
{v:15,t:"Vai ao faraó amanhã cedo, quando ele sair para ir à água; espera-o à beira do Rio e leva na mão o cajado que se transformou em serpente."},
{v:16,t:"Dize-lhe: O Senhor, o Deus dos hebreus, enviou-me a ti para dizer: Deixa partir o meu povo, para que me ofereça sacrifícios no deserto; mas até agora não quiseste ouvir."},
{v:17,t:"Assim diz o Senhor: Nisto saberás que eu sou o Senhor: com o cajado que tenho na mão vou ferir as águas do Rio, e elas se transformarão em sangue."},
{v:18,t:"Os peixes do Rio morrerão, o Rio ficará podre, e os egípcios terão nojo de beber a água do Rio."},
{v:19,t:"O Senhor disse ainda a Moisés: Dize a Aarão: Toma o teu cajado e estende a mão sobre as águas do Egito, sobre os seus rios, os seus canais, os seus pântanos e todos os seus reservatórios, para que se transformem em sangue; e haverá sangue em toda a terra do Egito, até nas vasilhas de madeira e de pedra.",np:1},
{v:20,t:"Moisés e Aarão fizeram como o Senhor tinha ordenado. Aarão levantou o cajado e feriu as águas do Rio diante do faraó e dos seus servos; e toda a água do Rio se transformou em sangue."},
{v:21,t:"Os peixes do Rio morreram, o Rio ficou podre, e os egípcios não podiam beber a água do Rio; e houve sangue em toda a terra do Egito."},
{v:22,t:"Mas os magos do Egito fizeram o mesmo com os seus encantamentos; e o coração do faraó se endureceu, e ele não os ouviu, como o Senhor tinha dito.",np:1},
{v:23,t:"O faraó deu as costas e voltou para casa, sem dar importância a isso."},
{v:24,t:"Todos os egípcios cavaram ao redor do Rio, em busca de água para beber, porque não podiam beber a água do Rio."},
{v:25,t:"Passaram-se sete dias depois que o Senhor feriu o Rio."},
{s:"Segunda praga: as rãs"},
{v:26,t:"O Senhor disse a Moisés: Vai ao faraó e dize-lhe: Assim diz o Senhor: Deixa partir o meu povo, para que me ofereça sacrifícios.",n:"Em outras Bíblias, 7,26–29 é 8,1–4, e a numeração do capítulo 8 diminui de quatro unidades."},
{v:27,t:"Se te recusares a deixá-lo partir, eu ferirei todo o teu território com rãs."},
{v:28,t:"O Rio fervilhará de rãs, que subirão e entrarão no teu palácio, no teu quarto de dormir e na tua cama, nas casas dos teus servos e do teu povo, nos teus fornos e nas tuas amassadeiras."},
{v:29,t:"As rãs subirão sobre ti, sobre o teu povo e sobre todos os teus servos."}
];

window.TEXTOS_SEED["exodo"][8] = [
{s:"As rãs cobrem o Egito"},
{v:1,t:"O Senhor disse a Moisés: Dize a Aarão: Estende a mão com o teu cajado sobre os rios, os canais e os pântanos, e faze subir as rãs sobre a terra do Egito.",n:"Em outras Bíblias, 8,1–28 é 8,5–32."},
{v:2,t:"Aarão estendeu a mão sobre as águas do Egito, e as rãs subiram e cobriram a terra do Egito."},
{v:3,t:"Mas os magos fizeram o mesmo com os seus encantamentos e fizeram subir rãs sobre a terra do Egito."},
{v:4,t:"O faraó chamou Moisés e Aarão e disse: Rogai ao Senhor que afaste as rãs de mim e do meu povo, e eu deixarei o povo partir para oferecer sacrifícios ao Senhor.",np:1},
{v:5,t:"Moisés disse ao faraó: Marca tu mesmo quando devo rogar por ti, pelos teus servos e pelo teu povo, para que as rãs se afastem de ti e das tuas casas e fiquem somente no Rio."},
{v:6,t:"Ele respondeu: Amanhã. Moisés disse: Será como disseste, para que saibas que não há ninguém como o Senhor, nosso Deus."},
{v:7,t:"As rãs se afastarão de ti, das tuas casas, dos teus servos e do teu povo; ficarão somente no Rio."},
{v:8,t:"Moisés e Aarão saíram da presença do faraó, e Moisés clamou ao Senhor a respeito das rãs, como tinha combinado com o faraó."},
{v:9,t:"O Senhor fez como Moisés tinha pedido: as rãs morreram nas casas, nos pátios e nos campos.",np:1},
{v:10,t:"Juntaram-nas em montões, e a terra ficou cheirando mal."},
{v:11,t:"Mas, quando o faraó viu que tinha alívio, endureceu o coração e não os ouviu, como o Senhor tinha dito."},
{s:"Terceira praga: os mosquitos"},
{v:12,t:"O Senhor disse a Moisés: Dize a Aarão: Estende o teu cajado e fere o pó da terra, e ele se transformará em mosquitos em toda a terra do Egito."},
{v:13,t:"Assim fizeram: Aarão estendeu a mão com o cajado e feriu o pó da terra, e houve mosquitos sobre os homens e sobre os animais; todo o pó da terra se transformou em mosquitos em toda a terra do Egito."},
{v:14,t:"Os magos tentaram fazer o mesmo com os seus encantamentos, para produzir mosquitos, mas não conseguiram. E os mosquitos estavam sobre os homens e sobre os animais;",np:1},
{v:15,t:"e os magos disseram ao faraó: Isto é o dedo de Deus. Mas o coração do faraó se endureceu, e ele não os ouviu, como o Senhor tinha dito.",n:"O dedo de Deus: os magos reconhecem o limite das suas artes. Jesus usa a mesma expressão para falar dos seus exorcismos (Lucas 11,20)."},
{s:"Quarta praga: as moscas"},
{v:16,t:"O Senhor disse a Moisés: Levanta-te cedo, apresenta-te ao faraó quando ele sair para ir à água e dize-lhe: Assim diz o Senhor: Deixa partir o meu povo, para que me ofereça sacrifícios."},
{v:17,t:"Se não deixares o meu povo partir, mandarei contra ti, contra os teus servos, contra o teu povo e contra as tuas casas enxames de moscas de toda espécie; as casas dos egípcios e até o chão em que pisam ficarão cheios de moscas."},
{v:18,t:"Mas naquele dia porei à parte a terra de Gessen, onde habita o meu povo, para que ali não haja moscas; assim saberás que eu, o Senhor, estou no meio desta terra."},
{v:19,t:"Farei distinção entre o meu povo e o teu povo; amanhã acontecerá este sinal."},
{v:20,t:"Assim fez o Senhor: enxames enormes de moscas entraram no palácio do faraó, nas casas dos seus servos e em toda a terra do Egito, e a terra ficou arruinada por causa das moscas."},
{v:21,t:"O faraó chamou Moisés e Aarão e disse: Ide oferecer sacrifícios ao vosso Deus, aqui no país.",np:1},
{v:22,t:"Moisés respondeu: Não convém fazer isso, porque os sacrifícios que oferecemos ao Senhor, nosso Deus, são uma abominação para os egípcios; se imolarmos diante deles os animais que os egípcios veneram, eles nos apedrejarão."},
{v:23,t:"Iremos ao deserto, a três dias de caminho, e ofereceremos sacrifícios ao Senhor, nosso Deus, como ele nos ordenou."},
{v:24,t:"O faraó disse: Eu vos deixarei partir para oferecerdes sacrifícios ao Senhor, vosso Deus, no deserto; mas não vos afasteis demais. Rogai por mim."},
{v:25,t:"Moisés disse: Logo que eu sair da tua presença, rogarei ao Senhor, e amanhã as moscas se afastarão do faraó, dos seus servos e do seu povo. Mas que o faraó não volte a nos enganar, recusando deixar o povo partir para oferecer sacrifícios ao Senhor."},
{v:26,t:"Moisés saiu da presença do faraó e rogou ao Senhor;"},
{v:27,t:"e o Senhor fez como Moisés tinha pedido: afastou as moscas do faraó, dos seus servos e do seu povo; não ficou nem uma."},
{v:28,t:"Mas também desta vez o faraó endureceu o coração e não deixou o povo partir."}
];

window.TEXTOS_SEED["exodo"][9] = [
{s:"Quinta praga: a peste dos animais"},
{v:1,t:"O Senhor disse a Moisés: Vai ao faraó e dize-lhe: Assim diz o Senhor, o Deus dos hebreus: Deixa partir o meu povo, para que me ofereça sacrifícios."},
{v:2,t:"Se te recusares a deixá-lo partir e continuares a retê-lo,"},
{v:3,t:"eis que a mão do Senhor ferirá com uma peste muito grave os teus rebanhos que estão nos campos: os cavalos, os jumentos, os camelos, os bois e as ovelhas."},
{v:4,t:"Mas o Senhor fará distinção entre os rebanhos de Israel e os rebanhos dos egípcios, e nada morrerá de tudo o que pertence aos filhos de Israel."},
{v:5,t:"O Senhor marcou o prazo, dizendo: Amanhã o Senhor fará isto no país."},
{v:6,t:"No dia seguinte o Senhor o fez: morreram todos os rebanhos dos egípcios, mas dos rebanhos dos filhos de Israel não morreu nenhum.",np:1,n:"Todos: modo de dizer; os rebanhos dos egípcios reaparecem na praga do granizo (9,19–21)."},
{v:7,t:"O faraó mandou verificar: não tinha morrido nenhum animal dos rebanhos de Israel. Mas o coração do faraó continuou obstinado, e ele não deixou o povo partir."},
{s:"Sexta praga: as úlceras"},
{v:8,t:"O Senhor disse a Moisés e a Aarão: Enchei as mãos de cinza de forno, e Moisés a atirará para o céu diante do faraó;"},
{v:9,t:"ela se tornará uma poeira sobre toda a terra do Egito e produzirá em homens e animais úlceras que se abrirão em feridas, em toda a terra do Egito."},
{v:10,t:"Eles tomaram cinza de forno e se apresentaram ao faraó; Moisés a atirou para o céu, e ela produziu em homens e animais úlceras que se abriam em feridas.",np:1},
{v:11,t:"Os magos não puderam ficar diante de Moisés por causa das úlceras, porque as úlceras estavam neles e em todos os egípcios."},
{v:12,t:"Mas o Senhor endureceu o coração do faraó, e ele não os ouviu, como o Senhor tinha dito a Moisés."},
{s:"Sétima praga: o granizo"},
{v:13,t:"O Senhor disse a Moisés: Levanta-te cedo, apresenta-te ao faraó e dize-lhe: Assim diz o Senhor, o Deus dos hebreus: Deixa partir o meu povo, para que me ofereça sacrifícios;"},
{v:14,t:"porque desta vez vou mandar todas as minhas pragas contra ti, contra os teus servos e contra o teu povo, para que saibas que não há ninguém como eu em toda a terra."},
{v:15,t:"Se eu já tivesse estendido a mão e ferido a ti e ao teu povo com a peste, tu terias desaparecido da terra."},
{v:16,t:"Mas eu te conservei para mostrar em ti o meu poder, e para que o meu nome seja anunciado em toda a terra.",n:"São Paulo cita este versículo em Romanos 9,17."},
{v:17,t:"Ainda te opões ao meu povo e não queres deixá-lo partir?"},
{v:18,t:"Pois amanhã, a esta mesma hora, farei cair uma chuva de granizo tão forte como nunca houve no Egito, desde o dia em que foi fundado até hoje."},
{v:19,t:"Manda, pois, desde já recolher os teus rebanhos e tudo o que tens no campo; porque o granizo cairá sobre todos os homens e animais que se encontrarem no campo e não tiverem sido recolhidos, e eles morrerão."},
{v:20,t:"Os servos do faraó que temeram a palavra do Senhor fizeram os seus escravos e os seus rebanhos se abrigarem nas casas;"},
{v:21,t:"mas os que não deram importância à palavra do Senhor deixaram os seus escravos e os seus rebanhos no campo."},
{v:22,t:"O Senhor disse a Moisés: Estende a mão para o céu, e cairá granizo em toda a terra do Egito, sobre os homens, sobre os animais e sobre toda a vegetação dos campos na terra do Egito.",np:1},
{v:23,t:"Moisés estendeu o cajado para o céu, e o Senhor mandou trovões e granizo, e raios caíram sobre a terra; o Senhor fez cair granizo sobre a terra do Egito."},
{v:24,t:"Caíam granizo e fogo misturados, e o granizo era tão violento como nunca tinha havido em toda a terra do Egito desde que ela se tornou uma nação."},
{v:25,t:"O granizo feriu em toda a terra do Egito tudo o que estava no campo, homens e animais; feriu toda a vegetação dos campos e quebrou todas as árvores do campo."},
{v:26,t:"Somente na terra de Gessen, onde estavam os filhos de Israel, não caiu granizo."},
{v:27,t:"O faraó mandou chamar Moisés e Aarão e lhes disse: Desta vez eu pequei; o Senhor é justo, e eu e o meu povo somos culpados.",np:1},
{v:28,t:"Rogai ao Senhor: já basta de trovões de Deus e de granizo. Eu vos deixarei partir, e não ficareis mais aqui.",np:1},
{v:29,t:"Moisés lhe disse: Quando eu sair da cidade, estenderei as mãos para o Senhor; os trovões cessarão, e não haverá mais granizo, para que saibas que a terra pertence ao Senhor.",np:1},
{v:30,t:"Mas eu sei que tu e os teus servos ainda não temeis o Senhor Deus.",np:1},
{v:31,t:"O linho e a cevada foram destruídos, porque a cevada já estava espigada, e o linho, em flor;",np:1},
{v:32,t:"mas o trigo e a espelta não foram destruídos, porque são tardios."},
{v:33,t:"Moisés saiu da presença do faraó e da cidade e estendeu as mãos para o Senhor; os trovões e o granizo cessaram, e a chuva parou de cair sobre a terra.",np:1},
{v:34,t:"Quando o faraó viu que a chuva, o granizo e os trovões tinham cessado, continuou a pecar:",np:1},
{v:35,t:"endureceu o coração, ele e os seus servos; o coração do faraó se endureceu, e ele não deixou partir os filhos de Israel, como o Senhor tinha dito por meio de Moisés."}
];

window.TEXTOS_SEED["exodo"][10] = [
{s:"Oitava praga: os gafanhotos"},
{v:1,t:"O Senhor disse a Moisés: Vai ao faraó, porque eu endureci o coração dele e o dos seus servos, para realizar estes meus sinais no meio deles,"},
{v:2,t:"e para que contes ao teu filho e ao teu neto como tratei os egípcios e os sinais que fiz no meio deles; e sabereis que eu sou o Senhor.",n:"A história das pragas é contada para ser transmitida de pai para filho: a memória da libertação faz parte da fé de Israel (compare 12,26–27; 13,8.14)."},
{v:3,t:"Moisés e Aarão foram ao faraó e lhe disseram: Assim diz o Senhor, o Deus dos hebreus: Até quando te recusarás a humilhar-te diante de mim? Deixa partir o meu povo, para que me ofereça sacrifícios.",np:1},
{v:4,t:"Se te recusares a deixá-lo partir, amanhã farei vir gafanhotos sobre o teu território,",np:1},
{v:5,t:"que cobrirão a face da terra, a ponto de não se poder ver o chão; eles devorarão o que escapou do granizo e roerão todas as árvores que brotam nos campos."},
{v:6,t:"Encherão o teu palácio, as casas dos teus servos e as casas de todos os egípcios, como nunca viram os teus pais nem os teus avós, desde que existem sobre a terra até hoje. E Moisés deu as costas e saiu da presença do faraó.",np:1},
{v:7,t:"Os servos do faraó lhe disseram: Até quando esse homem será uma armadilha para nós? Deixa esses homens partir, para que ofereçam sacrifícios ao Senhor, seu Deus. Ainda não vês que o Egito está arruinado?",np:1},
{v:8,t:"Mandaram chamar de novo Moisés e Aarão ao faraó, e ele lhes disse: Ide oferecer sacrifícios ao Senhor, vosso Deus. Mas quem são os que vão?",np:1},
{v:9,t:"Moisés respondeu: Iremos com as nossas crianças e os nossos velhos, com os nossos filhos e as nossas filhas, com as nossas ovelhas e os nossos bois, porque é uma festa do Senhor para nós.",np:1},
{v:10,t:"O faraó lhes disse: Que o Senhor esteja convosco, assim como eu vou deixar partir a vós e as vossas crianças! Está claro que tendes más intenções.",np:1,n:"Ironia do faraó: tão certo como o Senhor estará convosco, eu não vos deixarei partir com as crianças."},
{v:11,t:"Não será assim: ide somente vós, os homens, e oferecei sacrifícios ao Senhor, pois foi isso que pedistes. E os expulsaram da presença do faraó.",np:1},
{v:12,t:"O Senhor disse a Moisés: Estende a mão sobre a terra do Egito, para que venham os gafanhotos, subam sobre a terra do Egito e devorem toda a vegetação da terra, tudo o que o granizo deixou.",np:1},
{v:13,t:"Moisés estendeu o cajado sobre a terra do Egito, e o Senhor fez soprar um vento abrasador sobre a terra durante todo aquele dia e toda a noite. Pela manhã, o vento abrasador tinha trazido os gafanhotos."},
{v:14,t:"Os gafanhotos subiram sobre toda a terra do Egito e pousaram em todo o território egípcio, em quantidade enorme: nunca antes tinha havido tantos gafanhotos, nem haverá depois."},
{v:15,t:"Cobriram a face de toda a terra, e a terra ficou escura. Devoraram toda a vegetação da terra e todos os frutos das árvores que o granizo tinha deixado; não ficou nada verde nas árvores nem na vegetação dos campos, em todo o Egito."},
{v:16,t:"O faraó mandou chamar depressa Moisés e Aarão e disse: Pequei contra o Senhor, vosso Deus, e contra vós.",np:1},
{v:17,t:"Mas agora perdoai o meu pecado, só desta vez, e rogai ao Senhor, vosso Deus, que afaste de mim ao menos esta praga mortal."},
{v:18,t:"Moisés saiu da presença do faraó e rogou ao Senhor;"},
{v:19,t:"e o Senhor fez soprar do ocidente um vento muito forte, que levou os gafanhotos e os lançou no mar Vermelho; não ficou nem um gafanhoto em todo o território do Egito.",n:"Mar Vermelho: o hebraico diz mar dos Juncos; a tradução grega e a Vulgata o chamaram mar Vermelho, e é esse o nome que ficou."},
{v:20,t:"Mas o Senhor endureceu o coração do faraó, e ele não deixou partir os filhos de Israel."},
{s:"Nona praga: as trevas"},
{v:21,t:"O Senhor disse a Moisés: Estende a mão para o céu, e haverá sobre a terra do Egito trevas tão densas que se possam apalpar."},
{v:22,t:"Moisés estendeu a mão para o céu, e houve trevas espessas em toda a terra do Egito durante três dias."},
{v:23,t:"Ninguém via o seu irmão, e ninguém se movia do lugar onde estava; mas onde habitavam os filhos de Israel havia luz.",n:"As trevas atingem o sol, o maior dos deuses do Egito; a luz fica com Israel (compare Sabedoria 17,1–18,4)."},
{v:24,t:"O faraó chamou Moisés e Aarão e disse: Ide oferecer sacrifícios ao Senhor; só as vossas ovelhas e os vossos bois ficarão; as vossas crianças podem ir convosco.",np:1},
{v:25,t:"Moisés respondeu: Ainda que tu mesmo nos desses vítimas e holocaustos para oferecermos ao Senhor, nosso Deus,"},
{v:26,t:"os nossos rebanhos também irão conosco; não ficará nem um casco, porque é deles que tiraremos o que for necessário para o culto do Senhor, nosso Deus; e nós mesmos não sabemos o que devemos oferecer enquanto não chegarmos lá."},
{v:27,t:"Mas o Senhor endureceu o coração do faraó, e ele não quis deixá-los partir.",np:1},
{v:28,t:"O faraó disse a Moisés: Sai da minha presença! Toma cuidado para não voltares a ver o meu rosto, porque no dia em que o vires, morrerás."},
{v:29,t:"Moisés respondeu: Será como disseste: não verei mais o teu rosto."}
];

window.TEXTOS_SEED["exodo"][11] = [
{s:"O anúncio da última praga"},
{v:1,t:"O Senhor disse a Moisés: Ainda uma praga farei cair sobre o faraó e sobre o Egito; depois disso ele vos deixará partir daqui; mais ainda: ele vos expulsará."},
{v:2,t:"Dize, pois, ao povo que cada homem peça ao seu vizinho, e cada mulher à sua vizinha, objetos de prata e de ouro."},
{v:3,t:"O Senhor fez que o povo encontrasse favor aos olhos dos egípcios. E Moisés era um homem muito considerado na terra do Egito, aos olhos dos servos do faraó e de todo o povo."},
{v:4,t:"Moisés disse: Assim diz o Senhor: À meia-noite passarei pelo meio do Egito,",np:1},
{v:5,t:"e morrerá todo primogênito na terra do Egito, desde o primogênito do faraó, que se senta no seu trono, até o primogênito da escrava que está atrás da mó, e todos os primogênitos dos animais.",n:"Nota do tradutor: a morte dos primogênitos é o ponto mais duro da narrativa do Êxodo, e o texto não foi suavizado. Ela responde à ordem do faraó de matar os meninos hebreus (1,22) e à ameaça anunciada desde o começo (4,22–23)."},
{v:6,t:"Haverá um grande clamor em toda a terra do Egito, como nunca houve nem haverá jamais."},
{v:7,t:"Mas contra os filhos de Israel nem um cão latirá, nem contra os homens nem contra os animais, para que saibais que o Senhor faz distinção entre os egípcios e Israel."},
{v:8,t:"Então todos esses teus servos descerão até mim e se prostrarão diante de mim, dizendo: Sai, tu e todo o povo que te segue! E depois disso sairei. E Moisés saiu da presença do faraó, ardendo de ira."},
{v:9,t:"O Senhor disse a Moisés: O faraó não vos ouvirá, para que se multipliquem os meus prodígios na terra do Egito.",np:1},
{v:10,t:"Moisés e Aarão fizeram todos estes prodígios diante do faraó; mas o Senhor endureceu o coração do faraó, e ele não deixou os filhos de Israel saírem da sua terra."}
];

window.TEXTOS_SEED["exodo"][12] = [
{s:"A instituição da Páscoa"},
{v:1,t:"O Senhor disse a Moisés e a Aarão, na terra do Egito:"},
{v:2,t:"Este mês será para vós o princípio dos meses: será o primeiro mês do ano.",n:"O mês de Abib, mais tarde chamado Nisã, entre março e abril: o calendário de Israel começa pela libertação."},
{v:3,t:"Falai a toda a comunidade de Israel e dizei: No dia dez deste mês, cada um tomará um cordeiro por família, um cordeiro por casa."},
{v:4,t:"Se a família for pequena demais para um cordeiro, tomará consigo o vizinho mais próximo da sua casa, segundo o número de pessoas; calculareis o cordeiro conforme o que cada um pode comer."},
{v:5,t:"O cordeiro será sem defeito, macho, de um ano; podereis tomá-lo entre os cordeiros ou entre os cabritos,"},
{v:6,t:"e o guardareis até o dia catorze deste mês; e toda a assembleia da comunidade de Israel o imolará ao entardecer."},
{v:7,t:"Tomarão do seu sangue e o porão nos dois batentes e na verga da porta das casas em que o comerem;"},
{v:8,t:"e comerão a carne naquela noite, assada no fogo, com pães sem fermento e ervas amargas."},
{v:9,t:"Não comereis nada dele cru nem cozido na água, mas só assado no fogo, com a cabeça, as pernas e as entranhas."},
{v:10,t:"Não deixareis nada dele para a manhã seguinte; o que sobrar, vós o queimareis no fogo."},
{v:11,t:"Assim o comereis: com a cintura cingida, as sandálias nos pés e o cajado na mão; comereis às pressas. É a Páscoa do Senhor!",n:"A Nova Vulgata acrescenta entre parênteses a explicação de São Jerônimo: Páscoa, isto é, Passagem. Em hebraico, pesah soa como o verbo que significa passar adiante, poupar (12,13.23)."},
{v:12,t:"Naquela noite passarei pela terra do Egito e ferirei todos os primogênitos da terra do Egito, tanto dos homens como dos animais; e farei justiça contra todos os deuses do Egito, eu, o Senhor.",np:1},
{v:13,t:"O sangue será para vós um sinal nas casas em que estiverdes: quando eu vir o sangue, passarei adiante, e não haverá entre vós praga destruidora quando eu ferir a terra do Egito."},
{v:14,t:"Este dia será para vós um memorial, e o celebrareis como festa do Senhor; de geração em geração o celebrareis, como lei perpétua.",n:"Memorial: na liturgia de Israel, fazer memória é tornar presente a obra de Deus. Jesus celebrará a sua última ceia no contexto da Páscoa (Lucas 22,15–20; compare 1 Coríntios 5,7)."},
{s:"A festa dos Ázimos"},
{v:15,t:"Durante sete dias comereis pães sem fermento. Desde o primeiro dia tirareis o fermento das vossas casas; quem comer pão fermentado, do primeiro ao sétimo dia, essa pessoa será eliminada de Israel.",n:"Será eliminada: expressão que designa a exclusão da comunidade, e talvez a morte decretada por Deus."},
{v:16,t:"O primeiro dia será santo e solene, e o sétimo dia também será santo, com a mesma solenidade. Nesses dias não se fará nenhum trabalho, a não ser o preparo do que cada um deve comer.",np:1},
{v:17,t:"Observareis a festa dos Ázimos, porque foi neste mesmo dia que tirei os vossos exércitos da terra do Egito; observareis este dia de geração em geração, como lei perpétua.",np:1},
{v:18,t:"No primeiro mês, desde a tarde do dia catorze até a tarde do dia vinte e um, comereis pães sem fermento."},
{v:19,t:"Durante sete dias não se encontrará fermento nas vossas casas. Quem comer pão fermentado será eliminado da comunidade de Israel, seja estrangeiro, seja natural do país.",np:1},
{v:20,t:"Não comereis nada fermentado; em todas as vossas moradas comereis pães sem fermento."},
{s:"Moisés transmite as ordens"},
{v:21,t:"Moisés chamou todos os anciãos de Israel e lhes disse: Ide tomar um animal para cada família e imolai a Páscoa."},
{v:22,t:"Tomai um ramo de hissopo, molhai-o no sangue que estiver na bacia e marcai com o sangue a verga e os dois batentes da porta. E nenhum de vós saia da porta da sua casa até de manhã."},
{v:23,t:"Pois o Senhor passará para ferir os egípcios; mas, quando vir o sangue na verga e nos dois batentes, passará adiante da porta e não deixará o exterminador entrar nas vossas casas para ferir.",np:1},
{v:24,t:"Observareis esta ordem como lei perpétua para ti e para os teus filhos."},
{v:25,t:"Quando tiverdes entrado na terra que o Senhor vos dará, como prometeu, observareis este rito;"},
{v:26,t:"e, quando os vossos filhos vos perguntarem que rito é este,",n:"A pergunta dos filhos se tornou parte do rito pascal judaico: a noite da Páscoa é uma catequese em família."},
{v:27,t:"respondereis: É o sacrifício da Páscoa do Senhor, que passou adiante das casas dos filhos de Israel no Egito, quando feriu os egípcios e poupou as nossas casas. Então o povo se inclinou e se prostrou;"},
{v:28,t:"e os filhos de Israel foram e fizeram como o Senhor tinha ordenado a Moisés e a Aarão."},
{s:"A morte dos primogênitos"},
{v:29,t:"À meia-noite, o Senhor feriu todos os primogênitos na terra do Egito, desde o primogênito do faraó, que se sentava no seu trono, até o primogênito do prisioneiro que estava no cárcere, e todos os primogênitos dos animais."},
{v:30,t:"O faraó se levantou de noite, ele e todos os seus servos e todos os egípcios; e houve um grande clamor no Egito, porque não havia casa onde não houvesse um morto.",np:1},
{v:31,t:"O faraó chamou Moisés e Aarão de noite e disse: Levantai-vos, saí do meio do meu povo, vós e os filhos de Israel; ide oferecer sacrifícios ao Senhor, como dissestes.",np:1},
{v:32,t:"Levai também as vossas ovelhas e os vossos bois, como pedistes; ide, e abençoai-me também a mim."},
{v:33,t:"Os egípcios apressavam o povo a sair depressa do país, pois diziam: Vamos todos morrer!",np:1},
{v:34,t:"O povo levou a massa antes que fermentasse; e, amarrando as amassadeiras nos mantos, carregou-as nos ombros."},
{v:35,t:"Os filhos de Israel fizeram o que Moisés tinha dito e pediram aos egípcios objetos de prata e de ouro e muitas roupas.",np:1},
{v:36,t:"O Senhor fez que o povo encontrasse favor aos olhos dos egípcios, que lhes deram o que pediam; e assim despojaram os egípcios."},
{s:"A saída do Egito"},
{v:37,t:"Os filhos de Israel partiram de Ramessés para Sucot, cerca de seiscentos mil homens a pé, sem contar as crianças.",n:"Seiscentos mil homens, com as mulheres e as crianças, fariam mais de dois milhões de pessoas: o número exprime a grandeza do povo e da libertação, mais do que um recenseamento."},
{v:38,t:"Subiu também com eles uma multidão de gente misturada, e ovelhas e bois, um rebanho muito numeroso."},
{v:39,t:"Com a massa que tinham trazido do Egito, cozeram pães sem fermento, porque a massa não tinha fermentado: tinham sido expulsos do Egito sem poder demorar-se, e não tinham preparado provisões para si."},
{v:40,t:"A permanência dos filhos de Israel no Egito foi de quatrocentos e trinta anos.",np:1,n:"A tradução grega e o texto samaritano contam os quatrocentos e trinta anos a partir de Abraão, somando o tempo passado em Canaã; São Paulo segue essa contagem (Gálatas 3,17)."},
{v:41,t:"No fim dos quatrocentos e trinta anos, naquele mesmo dia, todos os exércitos do Senhor saíram da terra do Egito."},
{v:42,t:"Foi uma noite de vigília para o Senhor, quando os tirou da terra do Egito: esta noite, todos os filhos de Israel devem passá-la em vigília em honra do Senhor, de geração em geração.",n:"Desta noite de vigília nasceu a Vigília Pascal cristã, chamada por Santo Agostinho a mãe de todas as vigílias."},
{s:"Normas sobre a Páscoa"},
{v:43,t:"O Senhor disse a Moisés e a Aarão: Esta é a lei da Páscoa: nenhum estrangeiro comerá dela;"},
{v:44,t:"mas todo escravo comprado a dinheiro, depois de circuncidado, poderá comer dela;"},
{v:45,t:"o estrangeiro de passagem e o trabalhador assalariado não comerão dela."},
{v:46,t:"Será comida numa só casa; não levareis nenhum pedaço da carne para fora da casa, e não quebrareis nenhum dos seus ossos.",n:"São João aplica esta norma a Jesus crucificado, o verdadeiro cordeiro pascal (João 19,36)."},
{v:47,t:"Toda a comunidade de Israel a celebrará.",np:1},
{v:48,t:"Se um estrangeiro que mora contigo quiser celebrar a Páscoa do Senhor, todos os homens da sua casa deverão ser circuncidados; então poderá aproximar-se para celebrá-la e será como um natural do país. Mas nenhum incircunciso comerá dela."},
{v:49,t:"A mesma lei valerá para o natural do país e para o estrangeiro que mora no meio de vós."},
{v:50,t:"Todos os filhos de Israel fizeram como o Senhor tinha ordenado a Moisés e a Aarão;"},
{v:51,t:"e naquele mesmo dia o Senhor tirou da terra do Egito os filhos de Israel, organizados em exércitos."}
];

window.TEXTOS_SEED["exodo"][13] = [
{s:"A consagração dos primogênitos"},
{v:1,t:"O Senhor falou a Moisés e disse:"},
{v:2,t:"Consagra-me todo primogênito, todo o que abre o seio materno entre os filhos de Israel, tanto dos homens como dos animais: ele me pertence.",n:"O primogênito pertence a Deus, que poupou os primogênitos de Israel na noite da Páscoa (13,15). Maria e José apresentam Jesus no templo segundo esta lei (Lucas 2,22–23)."},
{v:3,t:"Moisés disse ao povo: Lembrai-vos deste dia, em que saístes do Egito, da casa da escravidão, porque o Senhor vos tirou daqui com mão poderosa; não se comerá pão fermentado.",np:1},
{v:4,t:"Hoje saís, no mês de Abib.",n:"Abib quer dizer espigas novas, como explica a Nova Vulgata, seguindo São Jerônimo."},
{v:5,t:"Quando o Senhor te tiver introduzido na terra dos cananeus, dos heteus, dos amorreus, dos heveus e dos jebuseus, que jurou aos teus pais que te daria, terra onde corre leite e mel, celebrarás este rito neste mês."},
{v:6,t:"Durante sete dias comerás pães sem fermento, e no sétimo dia haverá uma festa em honra do Senhor.",np:1},
{v:7,t:"Comerás pães sem fermento durante os sete dias; não se verá contigo pão fermentado, nem fermento em todo o teu território.",np:1},
{v:8,t:"Naquele dia explicarás ao teu filho: É por causa do que o Senhor fez por mim quando saí do Egito."},
{v:9,t:"Isto será para ti como um sinal na tua mão e como uma lembrança entre os teus olhos, para que a lei do Senhor esteja sempre na tua boca; pois foi com mão poderosa que o Senhor te tirou do Egito."},
{v:10,t:"Observarás este rito no tempo marcado, de ano em ano.",np:1},
{v:11,t:"Quando o Senhor te tiver introduzido na terra dos cananeus, como jurou a ti e aos teus pais, e a tiver dado a ti,",np:1},
{v:12,t:"consagrarás ao Senhor todo o que abre o seio materno; também todo primeiro filhote do teu gado, se for macho, pertencerá ao Senhor."},
{v:13,t:"Resgatarás com um cordeiro todo primeiro filhote de jumenta; se não o resgatares, tu o matarás. Mas resgatarás todo primogênito dos teus filhos."},
{v:14,t:"E, quando amanhã o teu filho te perguntar o que significa isso, tu lhe responderás: Com mão poderosa o Senhor nos tirou do Egito, da casa da escravidão."},
{v:15,t:"Como o faraó se obstinava em não nos deixar partir, o Senhor matou todos os primogênitos na terra do Egito, desde o primogênito do homem até o primogênito dos animais; por isso eu sacrifico ao Senhor todo macho que abre o seio materno, e resgato todo primogênito dos meus filhos."},
{v:16,t:"Isto será como um sinal na tua mão e como um distintivo entre os teus olhos, porque o Senhor nos tirou do Egito com mão poderosa.",n:"Israel tomou estas palavras à letra: delas vêm os filactérios, pequenos estojos com textos da Lei, atados ao braço e à testa para a oração (compare Deuteronômio 6,8)."},
{s:"O caminho do deserto"},
{v:17,t:"Quando o faraó deixou o povo partir, Deus não o conduziu pelo caminho da terra dos filisteus, embora fosse o mais curto, porque pensou: Não aconteça que o povo, vendo-se diante da guerra, se arrependa e volte para o Egito;"},
{v:18,t:"mas o fez dar uma volta pelo caminho do deserto, junto ao mar Vermelho. E os filhos de Israel subiram armados da terra do Egito."},
{v:19,t:"Moisés levou consigo os ossos de José, porque José tinha feito os filhos de Israel jurarem, dizendo: Deus vos visitará; levai daqui convosco os meus ossos.",n:"Cumpre-se o juramento de Gênesis 50,25."},
{v:20,t:"Partiram de Sucot e acamparam em Etam, na orla do deserto.",np:1},
{v:21,t:"O Senhor ia à frente deles, de dia numa coluna de nuvem, para lhes mostrar o caminho, e de noite numa coluna de fogo, para os iluminar; assim podiam caminhar de dia e de noite."},
{v:22,t:"A coluna de nuvem durante o dia e a coluna de fogo durante a noite nunca se afastavam da frente do povo."}
];

window.TEXTOS_SEED["exodo"][14] = [
{s:"A travessia do mar"},
{v:1,t:"O Senhor falou a Moisés e disse:"},
{v:2,t:"Dize aos filhos de Israel que voltem atrás e acampem diante de Fiairot, entre Magdol e o mar, defronte de Baal-Sefon; acampareis diante desse lugar, junto ao mar."},
{v:3,t:"O faraó dirá dos filhos de Israel: Estão perdidos no país; o deserto os cercou."},
{v:4,t:"Eu endurecerei o coração do faraó, e ele os perseguirá; mas eu serei glorificado à custa do faraó e de todo o seu exército, e os egípcios saberão que eu sou o Senhor. E os israelitas assim fizeram."},
{v:5,t:"Anunciaram ao rei do Egito que o povo tinha fugido; e o coração do faraó e dos seus servos mudou em relação ao povo, e disseram: Que fizemos, deixando Israel sair do nosso serviço?",np:1},
{v:6,t:"O faraó mandou atrelar o seu carro e levou consigo o seu exército;"},
{v:7,t:"tomou seiscentos carros escolhidos e todos os carros do Egito, com oficiais em cada um deles."},
{v:8,t:"O Senhor endureceu o coração do faraó, rei do Egito, e ele perseguiu os filhos de Israel; mas os filhos de Israel tinham saído de mão levantada."},
{v:9,t:"Os egípcios os perseguiram e os alcançaram acampados junto ao mar: todos os cavalos e carros do faraó, os seus cavaleiros e o seu exército estavam junto de Fiairot, defronte de Baal-Sefon."},
{v:10,t:"Quando o faraó se aproximava, os filhos de Israel levantaram os olhos e viram que os egípcios marchavam atrás deles; tiveram muito medo e clamaram ao Senhor;",np:1},
{v:11,t:"e disseram a Moisés: Será que não havia sepulturas no Egito, para nos trazeres a morrer no deserto? Que nos fizeste, tirando-nos do Egito?"},
{v:12,t:"Não era isto que te dizíamos no Egito: Deixa-nos servir os egípcios? Melhor nos era servir os egípcios do que morrer no deserto."},
{v:13,t:"Moisés respondeu ao povo: Não tenhais medo! Ficai firmes e vede a salvação que o Senhor vai realizar hoje em vosso favor; os egípcios que hoje vedes, nunca mais os vereis."},
{v:14,t:"O Senhor combaterá por vós, e vós ficareis tranquilos."},
{v:15,t:"O Senhor disse a Moisés: Por que clamas a mim? Dize aos filhos de Israel que se ponham em marcha.",np:1},
{v:16,t:"E tu, levanta o teu cajado, estende a mão sobre o mar e divide-o, para que os filhos de Israel passem pelo meio do mar, em terra seca."},
{v:17,t:"Eu endurecerei o coração dos egípcios, e eles entrarão atrás deles; e serei glorificado à custa do faraó e de todo o seu exército, dos seus carros e dos seus cavaleiros.",np:1},
{v:18,t:"E os egípcios saberão que eu sou o Senhor, quando eu for glorificado à custa do faraó, dos seus carros e dos seus cavaleiros."},
{v:19,t:"O anjo de Deus, que ia à frente do acampamento de Israel, mudou de lugar e passou para trás deles; também a coluna de nuvem deixou a frente e se pôs atrás deles,",np:1},
{v:20,t:"ficando entre o acampamento dos egípcios e o acampamento de Israel; a nuvem era escura de um lado e iluminava a noite do outro, de modo que durante toda a noite um não pôde aproximar-se do outro."},
{v:21,t:"Moisés estendeu a mão sobre o mar, e o Senhor fez recuar o mar com um vento forte e abrasador, que soprou a noite toda, e o mar ficou seco; as águas se dividiram.",np:1},
{v:22,t:"Os filhos de Israel entraram pelo meio do mar em terra seca, e as águas formavam como uma muralha à direita e à esquerda deles."},
{v:23,t:"Os egípcios os perseguiram e entraram atrás deles até o meio do mar: todos os cavalos do faraó, os seus carros e os seus cavaleiros."},
{v:24,t:"Na vigília da manhã, o Senhor olhou da coluna de fogo e de nuvem para o acampamento dos egípcios e lançou a confusão no seu exército;"},
{v:25,t:"travou as rodas dos seus carros, de modo que só avançavam com dificuldade. Então os egípcios disseram: Fujamos de Israel, porque o Senhor combate por eles contra nós!"},
{v:26,t:"O Senhor disse a Moisés: Estende a mão sobre o mar, para que as águas voltem sobre os egípcios, sobre os seus carros e os seus cavaleiros.",np:1},
{v:27,t:"Moisés estendeu a mão sobre o mar, e ao romper da manhã o mar voltou ao seu lugar; os egípcios, fugindo, foram ao encontro das águas, e o Senhor os precipitou no meio do mar."},
{v:28,t:"As águas voltaram e cobriram os carros e os cavaleiros de todo o exército do faraó, que tinham entrado no mar atrás deles; não escapou nem um só."},
{v:29,t:"Mas os filhos de Israel caminharam em terra seca pelo meio do mar, e as águas formavam como uma muralha à direita e à esquerda deles."},
{v:30,t:"Naquele dia o Senhor salvou Israel da mão dos egípcios, e Israel viu os egípcios mortos à beira do mar;",np:1},
{v:31,t:"viu a grande obra que o Senhor tinha realizado contra os egípcios; e o povo temeu o Senhor e acreditou no Senhor e em Moisés, seu servo.",n:"A travessia do mar é o coração da fé de Israel e, para os cristãos, figura do batismo (1 Coríntios 10,1–2)."}
];

window.TEXTOS_SEED["exodo"][15] = [
{s:"O cântico de Moisés"},
{v:1,l:["Então Moisés e os filhos de Israel cantaram este cântico ao Senhor, dizendo:","Cantemos ao Senhor,","que se cobriu de glória:","cavalo e cavaleiro","ele lançou no mar!"],n:"Um dos poemas mais antigos da Bíblia. A Igreja o canta na Vigília Pascal, depois da leitura da travessia do mar."},
{v:2,l:["O Senhor é a minha força e o meu vigor,","ele foi a minha salvação.","Ele é o meu Deus,","e eu o glorificarei;","o Deus de meu pai,","e eu o exaltarei!"],np:1},
{v:3,l:["O Senhor é um guerreiro;","Senhor é o seu nome!"],np:1},
{v:4,l:["Os carros do faraó e o seu exército","ele lançou no mar;","os seus melhores guerreiros","afundaram no mar Vermelho."],np:1},
{v:5,l:["Os abismos os cobriram,","desceram às profundezas como uma pedra."],np:1},
{v:6,l:["A tua direita, Senhor,","é magnífica em poder;","a tua direita, Senhor,","esmagou o inimigo."],np:1},
{v:7,l:["Na grandeza da tua glória","derrubaste os teus adversários;","soltaste a tua ira,","que os devorou como palha."],np:1},
{v:8,l:["Ao sopro da tua ira","as águas se amontoaram;","as ondas se ergueram","como um dique,","os abismos se coalharam","no meio do mar."],np:1},
{v:9,l:["O inimigo dizia:","Vou persegui-los, alcançá-los,","repartir os despojos;","vou saciar-me deles,","desembainhar a espada:","a minha mão os destruirá!"],np:1},
{v:10,l:["Sopraste com o teu vento,","e o mar os cobriu;","afundaram como chumbo","nas águas impetuosas."],np:1},
{v:11,l:["Quem é semelhante a ti","entre os deuses, Senhor?","Quem é semelhante a ti,","magnífico em santidade,","terrível e digno de louvor,","que realizas maravilhas?"],np:1},
{v:12,l:["Estendeste a tua direita,","e a terra os engoliu."],np:1},
{v:13,l:["Guiaste com o teu amor","o povo que resgataste,","e com o teu poder o conduziste","à tua santa morada."],np:1},
{v:14,l:["Os povos ouviram e tremeram;","as dores se apoderaram dos habitantes da Filisteia."],np:1},
{v:15,l:["Então os chefes de Edom se perturbaram,","o tremor tomou conta dos poderosos de Moab,","todos os habitantes de Canaã ficaram paralisados."],np:1},
{v:16,l:["Caíram sobre eles","o terror e o pavor;","pela grandeza do teu braço","ficaram imóveis como pedra,","até que passasse o teu povo, Senhor,","até que passasse este povo","que adquiriste."],np:1},
{v:17,l:["Tu os levarás e os plantarás","no monte da tua herança,","no lugar que fizeste, Senhor,","para a tua morada,","no santuário, Senhor,","que as tuas mãos estabeleceram."],np:1,n:"O monte da tua herança: o monte Sião, onde será construído o templo. O cântico, cantado por séculos em Israel, já olha para a chegada à terra."},
{v:18,l:["O Senhor reinará","para sempre e eternamente!"],np:1},
{v:19,t:"Pois os cavalos do faraó, com os seus carros e cavaleiros, entraram no mar, e o Senhor fez voltar sobre eles as águas do mar; mas os filhos de Israel caminharam em terra seca pelo meio do mar.",np:1},
{v:20,t:"Então a profetisa Míriam, irmã de Aarão, tomou na mão um tamborim, e todas as mulheres saíram atrás dela com tamborins, dançando;",n:"Míriam: em hebraico Miryam, o mesmo nome que em grego se tornou Maria, e assim o escreve a Nova Vulgata."},
{v:21,l:["e Míriam entoava para elas:","Cantai ao Senhor,","que se cobriu de glória:","cavalo e cavaleiro","ele lançou no mar!"],np:1},
{s:"As águas de Mara"},
{v:22,t:"Moisés fez Israel partir do mar Vermelho, e eles saíram para o deserto de Sur; caminharam três dias pelo deserto sem encontrar água."},
{v:23,t:"Chegaram a Mara, mas não puderam beber as águas de Mara, porque eram amargas; por isso deram ao lugar o nome de Mara.",n:"Mara quer dizer amargura, como explica a Nova Vulgata, seguindo São Jerônimo."},
{v:24,t:"O povo murmurou contra Moisés, dizendo: Que vamos beber?"},
{v:25,t:"Moisés clamou ao Senhor, e o Senhor lhe mostrou um pedaço de madeira; Moisés o lançou nas águas, e as águas se tornaram doces. Ali o Senhor deu ao povo uma lei e um direito, e ali o pôs à prova,"},
{v:26,t:"dizendo: Se ouvires atentamente a voz do Senhor, teu Deus, e fizeres o que é reto aos seus olhos, se obedeceres aos seus mandamentos e guardares todos os seus preceitos, não mandarei sobre ti nenhuma das doenças que mandei sobre o Egito, pois eu sou o Senhor, aquele que te cura."},
{v:27,t:"Chegaram a Elim, onde havia doze fontes de água e setenta palmeiras; e acamparam ali, junto às águas.",np:1}
];

window.TEXTOS_SEED["exodo"][16] = [
{s:"O maná e as codornizes"},
{v:1,t:"Partiram de Elim, e toda a comunidade dos filhos de Israel chegou ao deserto de Sin, que fica entre Elim e o Sinai, no dia quinze do segundo mês depois da saída da terra do Egito."},
{v:2,t:"No deserto, toda a comunidade dos filhos de Israel murmurou contra Moisés e Aarão,",np:1},
{v:3,t:"e os filhos de Israel lhes disseram: Antes tivéssemos morrido pela mão do Senhor na terra do Egito, quando nos sentávamos junto às panelas de carne e comíamos pão à vontade! Por que nos trouxestes a este deserto, para matar de fome toda esta multidão?"},
{v:4,t:"O Senhor disse a Moisés: Eis que farei chover pão do céu para vós; o povo sairá e recolherá cada dia a porção de cada dia, para que eu o ponha à prova e veja se anda ou não segundo a minha lei.",np:1,n:"Pão do céu: Jesus retoma a imagem e se apresenta como o verdadeiro pão descido do céu (João 6,31–35)."},
{v:5,t:"No sexto dia, quando prepararem o que tiverem trazido, haverá o dobro do que recolhem nos outros dias."},
{v:6,l:["Moisés e Aarão disseram a todos os filhos de Israel:","Esta tarde sabereis","que foi o Senhor quem vos tirou","da terra do Egito;"],np:1},
{v:7,l:["e amanhã vereis","a glória do Senhor.","Pois ele ouviu as vossas murmurações contra o Senhor. E nós, quem somos, para murmurardes contra nós?"],np:1},
{v:8,l:["E Moisés disse:","O Senhor vos dará","à tarde carne para comer","e pela manhã pão à vontade,","porque ouviu as murmurações que fizestes contra ele. Pois nós, quem somos? Não é contra nós que murmurais, mas contra o Senhor."],np:1},
{v:9,t:"Moisés disse a Aarão: Dize a toda a comunidade dos filhos de Israel: Aproximai-vos da presença do Senhor, porque ele ouviu as vossas murmurações.",np:1},
{v:10,t:"Enquanto Aarão falava a toda a comunidade dos filhos de Israel, eles se voltaram para o deserto, e eis que a glória do Senhor apareceu na nuvem."},
{v:11,t:"O Senhor falou a Moisés e disse:"},
{v:12,t:"Ouvi as murmurações dos filhos de Israel. Dize-lhes: Ao entardecer comereis carne, e pela manhã vos fartareis de pão; e sabereis que eu sou o Senhor, vosso Deus."},
{v:13,t:"À tarde subiram codornizes, que cobriram o acampamento; e pela manhã havia uma camada de orvalho ao redor do acampamento.",np:1},
{v:14,t:"Quando a camada de orvalho evaporou, apareceu sobre a superfície do deserto uma coisa miúda, granulosa, fina como a geada sobre a terra.",np:1},
{v:15,t:"Ao vê-la, os filhos de Israel perguntavam uns aos outros: Man hu? Pois não sabiam o que era. Moisés lhes disse: Este é o pão que o Senhor vos deu para comer.",n:"Man hu, isto é, que é isto: a Nova Vulgata reproduz entre parênteses a explicação de São Jerônimo. Daí o nome maná (16,31)."},
{v:16,t:"Eis o que o Senhor ordenou: Recolha cada um o quanto precisa para comer, um ômer por pessoa, segundo o número de pessoas que cada um tiver na sua tenda."},
{v:17,t:"Os filhos de Israel assim fizeram, e recolheram uns mais, outros menos."},
{v:18,t:"Quando o mediram com o ômer, quem tinha recolhido mais não teve de sobra, e quem tinha recolhido menos não teve falta: cada um tinha recolhido o que podia comer.",np:1,n:"São Paulo cita este versículo a propósito da partilha entre as Igrejas (2 Coríntios 8,15)."},
{v:19,t:"Moisés lhes disse: Ninguém deixe nada para a manhã seguinte.",np:1},
{v:20,t:"Mas eles não ouviram Moisés, e alguns deixaram uma parte para a manhã seguinte; mas encheu-se de vermes e cheirou mal. E Moisés se irritou contra eles."},
{v:21,t:"Recolhiam-no todas as manhãs, cada um o quanto precisava para comer; e, quando o sol esquentava, ele se derretia."},
{s:"O maná e o sábado"},
{v:22,t:"No sexto dia recolheram o dobro de pão, dois ômeres por pessoa. Todos os chefes da comunidade vieram contar isso a Moisés."},
{v:23,t:"Ele lhes disse: É isto o que o Senhor disse: Amanhã é dia de repouso, sábado consagrado ao Senhor. Assai o que tiverdes de assar e cozinhai o que tiverdes de cozinhar; e o que sobrar, guardai-o para amanhã.",np:1},
{v:24,t:"Eles o guardaram para a manhã seguinte, como Moisés tinha ordenado, e não cheirou mal nem se encheu de vermes."},
{v:25,t:"Moisés disse: Comei-o hoje, porque hoje é sábado em honra do Senhor; hoje não o encontrareis no campo.",np:1},
{v:26,t:"Recolhereis durante seis dias; mas o sétimo dia é sábado: nesse dia não haverá maná."},
{v:27,t:"No sétimo dia, alguns do povo saíram para recolher, mas não encontraram nada.",np:1},
{v:28,t:"O Senhor disse a Moisés: Até quando vos recusareis a guardar os meus mandamentos e as minhas leis?"},
{v:29,t:"Vede: o Senhor vos deu o sábado; por isso, no sexto dia, ele vos dá pão para dois dias. Que cada um fique onde está: ninguém saia do seu lugar no sétimo dia."},
{v:30,t:"E o povo descansou no sétimo dia."},
{v:31,t:"A casa de Israel deu a esse alimento o nome de maná; era como semente de coentro, branco, e o seu sabor era como o de bolo de flor de farinha com mel.",np:1},
{v:32,t:"Moisés disse: É isto o que o Senhor ordenou: Enchei um ômer de maná e guardai-o para as vossas gerações, para que vejam o pão com que vos alimentei no deserto, quando vos tirei da terra do Egito.",np:1},
{v:33,t:"Moisés disse a Aarão: Toma um vaso, põe nele um ômer cheio de maná e deposita-o diante do Senhor, para ser guardado para as vossas gerações."},
{v:34,t:"Como o Senhor tinha ordenado a Moisés, Aarão o depositou diante do Testemunho, para ser guardado.",n:"O Testemunho: as tábuas da Lei, guardadas na arca (25,16); o narrador antecipa o que ainda vai acontecer (compare Hebreus 9,4)."},
{v:35,t:"Os filhos de Israel comeram o maná durante quarenta anos, até chegarem a uma terra habitada; comeram o maná até chegarem aos limites da terra de Canaã.",np:1},
{v:36,t:"O ômer é a décima parte do efá.",np:1}
];

window.TEXTOS_SEED["exodo"][17] = [
{s:"A água que sai da rocha"},
{v:1,t:"Toda a comunidade dos filhos de Israel partiu do deserto de Sin, em etapas, conforme a ordem do Senhor, e acampou em Rafidim, onde não havia água para o povo beber."},
{v:2,t:"O povo discutiu com Moisés, dizendo: Dá-nos água para beber! Moisés lhes respondeu: Por que discutis comigo? Por que tentais o Senhor?"},
{v:3,t:"Mas o povo tinha sede e murmurou contra Moisés, dizendo: Por que nos fizeste sair do Egito, para nos matar de sede, a nós, aos nossos filhos e aos nossos rebanhos?"},
{v:4,t:"Moisés clamou ao Senhor, dizendo: Que farei com este povo? Mais um pouco e me apedrejarão."},
{v:5,t:"O Senhor disse a Moisés: Passa à frente do povo, leva contigo alguns anciãos de Israel, toma na mão o cajado com que feriste o Rio, e vai.",np:1},
{v:6,t:"Eis que eu estarei ali diante de ti, sobre a rocha, no Horeb; ferirás a rocha, e dela sairá água, para que o povo beba. Moisés assim fez, diante dos anciãos de Israel.",n:"São Paulo vê nesta rocha uma figura de Cristo, que acompanhava o povo no deserto (1 Coríntios 10,4)."},
{v:7,t:"E deu àquele lugar o nome de Massá e Meribá, por causa da discussão dos filhos de Israel e porque tentaram o Senhor, dizendo: O Senhor está ou não está no meio de nós?",n:"Massá quer dizer tentação, e Meribá, contenda (compare Salmo 95,8–9; Números 20,1–13)."},
{s:"A batalha contra Amalec"},
{v:8,t:"Amalec veio e atacou Israel em Rafidim."},
{v:9,t:"Moisés disse a Josué: Escolhe para nós alguns homens e sai para combater contra Amalec; amanhã eu ficarei de pé no alto da colina, com o cajado de Deus na mão.",n:"Primeira menção de Josué, o futuro sucessor de Moisés."},
{v:10,t:"Josué fez como Moisés lhe tinha dito e combateu contra Amalec; e Moisés, Aarão e Hur subiram ao alto da colina."},
{v:11,t:"Enquanto Moisés mantinha as mãos levantadas, Israel vencia; quando as abaixava, Amalec vencia."},
{v:12,t:"Mas as mãos de Moisés ficaram pesadas; então tomaram uma pedra e a puseram debaixo dele, e ele se sentou; Aarão e Hur sustentavam as suas mãos, um de um lado e o outro do outro. Assim as suas mãos ficaram firmes até o pôr do sol.",n:"Os Padres da Igreja viram nas mãos levantadas de Moisés uma imagem da oração perseverante e da cruz."},
{v:13,t:"E Josué derrotou Amalec e o seu povo ao fio da espada."},
{v:14,t:"O Senhor disse a Moisés: Escreve isto num livro, como memorial, e repete-o aos ouvidos de Josué: eu apagarei a memória de Amalec de debaixo do céu.",n:"Nota do tradutor: a sentença contra Amalec é dura e será retomada várias vezes (Deuteronômio 25,17–19; 1 Samuel 15); o texto não foi suavizado."},
{v:15,t:"Moisés construiu um altar e lhe deu o nome de Senhor-Nissi,",n:"Senhor-Nissi quer dizer o Senhor é a minha bandeira, como explica a Nova Vulgata, seguindo São Jerônimo."},
{v:16,l:["dizendo:","Uma mão se ergueu contra o trono do Senhor:","o Senhor está em guerra contra Amalec","de geração em geração."],n:"Texto obscuro; talvez: a mão sobre a bandeira do Senhor, como gesto de juramento."}
];

window.TEXTOS_SEED["exodo"][18] = [
{s:"Jetro visita Moisés"},
{v:1,t:"Jetro, sacerdote de Madiã e sogro de Moisés, ouviu falar de tudo o que Deus tinha feito por Moisés e por Israel, o seu povo, e de como o Senhor tinha tirado Israel do Egito,"},
{v:2,t:"e tomou consigo Séfora, mulher de Moisés, que este tinha mandado de volta,"},
{v:3,t:"e os dois filhos dela. Um se chamava Gersam, porque Moisés tinha dito: Fui um estrangeiro em terra estranha;"},
{v:4,t:"e o outro se chamava Eliezer, porque tinha dito: O Deus de meu pai foi o meu auxílio e me livrou da espada do faraó.",n:"Eliezer quer dizer meu Deus é auxílio."},
{v:5,t:"Jetro, sogro de Moisés, veio com os filhos e a mulher de Moisés ao deserto onde ele estava acampado, junto à montanha de Deus;"},
{v:6,t:"e mandou dizer a Moisés: Eu, Jetro, teu sogro, venho ao teu encontro, com a tua mulher e os seus dois filhos."},
{v:7,t:"Moisés saiu ao encontro do sogro, prostrou-se diante dele e o beijou; perguntaram um ao outro como estavam. E, quando entraram na tenda,",np:1},
{v:8,t:"Moisés contou ao sogro tudo o que o Senhor tinha feito ao faraó e aos egípcios por causa de Israel, todas as dificuldades que tinham encontrado no caminho e como o Senhor os tinha livrado."},
{v:9,t:"Jetro se alegrou por todo o bem que o Senhor tinha feito a Israel, livrando-o da mão dos egípcios,"},
{v:10,t:"e disse: Bendito seja o Senhor, que vos livrou da mão dos egípcios e da mão do faraó."},
{v:11,t:"Agora sei que o Senhor é maior do que todos os deuses, pois livrou o povo da mão dos egípcios, que os tinham tratado com arrogância."},
{v:12,t:"Jetro, sogro de Moisés, ofereceu a Deus um holocausto e sacrifícios; e Aarão e todos os anciãos de Israel vieram comer com o sogro de Moisés diante de Deus.",n:"Um sacerdote estrangeiro reconhece o Senhor e preside um sacrifício diante dos anciãos de Israel."},
{s:"O conselho de Jetro"},
{v:13,t:"No dia seguinte, Moisés sentou-se para julgar o povo, e o povo ficou de pé diante de Moisés desde a manhã até a tarde."},
{v:14,t:"Vendo tudo o que Moisés fazia pelo povo, o sogro lhe disse: Que é isso que fazes com o povo? Por que te sentas sozinho, enquanto todo o povo fica de pé diante de ti desde a manhã até a tarde?"},
{v:15,t:"Moisés respondeu ao sogro: É que o povo vem a mim para consultar a Deus."},
{v:16,t:"Quando têm alguma questão, vêm a mim, e eu julgo entre um e outro e lhes dou a conhecer os decretos de Deus e as suas leis."},
{v:17,t:"O sogro de Moisés lhe disse: Não está certo o que fazes."},
{v:18,t:"Tu te esgotarás, e também este povo que está contigo. A tarefa é pesada demais para ti; não poderás realizá-la sozinho."},
{v:19,t:"Ouve, pois, o meu conselho, e que Deus esteja contigo: representa tu o povo diante de Deus e leva as suas questões a Deus;"},
{v:20,t:"ensina-lhes os decretos e as leis, mostra-lhes o caminho que devem seguir e o que devem fazer."},
{v:21,t:"Mas escolhe dentre todo o povo homens capazes, que temam a Deus, homens íntegros, que odeiem o suborno, e põe-nos à frente do povo como chefes de mil, de cem, de cinquenta e de dez,"},
{v:22,t:"para que julguem o povo em todo tempo. Que te tragam todas as questões graves, e julguem eles mesmos as questões menores; assim aliviarás o teu fardo, e eles o carregarão contigo."},
{v:23,t:"Se fizeres isto, cumprirás a ordem de Deus e poderás levar a cabo os seus preceitos, e todo este povo voltará em paz para as suas casas."},
{v:24,t:"Moisés ouviu o sogro e fez tudo o que ele lhe tinha sugerido.",np:1},
{v:25,t:"Escolheu em todo Israel homens capazes e os pôs à frente do povo como chefes de mil, de cem, de cinquenta e de dez,"},
{v:26,t:"que julgavam o povo em todo tempo: as questões difíceis levavam a Moisés, e as questões menores julgavam eles mesmos."},
{v:27,t:"Depois Moisés despediu o sogro, que voltou para a sua terra."}
];

window.TEXTOS_SEED["exodo"][19] = [
{s:"A chegada ao Sinai"},
{v:1,t:"No terceiro mês depois da saída do Egito, naquele mesmo dia, os filhos de Israel chegaram ao deserto do Sinai.",n:"Naquele mesmo dia: a tradição judaica situou aqui a festa de Pentecostes, cinquenta dias depois da Páscoa, como memória do dom da Lei; os cristãos celebram nela o dom do Espírito (Atos 2)."},
{v:2,t:"Tinham partido de Rafidim e, chegando ao deserto do Sinai, acamparam ali; e Israel armou as suas tendas diante da montanha."},
{v:3,l:["Moisés subiu até Deus, e o Senhor o chamou da montanha e disse:","Assim dirás à casa de Jacó","e anunciarás aos filhos de Israel:"],np:1},
{v:4,l:["Vós mesmos vistes o que fiz aos egípcios,","como vos levei sobre asas de águia","e vos trouxe a mim."],np:1},
{v:5,l:["Agora, pois, se ouvirdes a minha voz","e guardardes a minha aliança,","sereis para mim uma propriedade particular entre todos os povos;","porque toda a terra é minha."],np:1},
{v:6,l:["Vós sereis para mim um reino de sacerdotes","e uma nação santa.","São estas as palavras que dirás aos filhos de Israel."],np:1,n:"A Primeira Carta de Pedro aplica estas palavras aos batizados (1 Pedro 2,9; compare Apocalipse 1,6)."},
{v:7,t:"Moisés veio, convocou os anciãos do povo e lhes expôs todas estas palavras que o Senhor lhe tinha ordenado.",np:1},
{v:8,t:"Todo o povo respondeu a uma só voz: Faremos tudo o que o Senhor disse. E, quando Moisés levou ao Senhor a resposta do povo,"},
{v:9,t:"o Senhor lhe disse: Eis que virei a ti numa nuvem espessa, para que o povo me ouça falar contigo e acredite em ti para sempre. E, quando Moisés transmitiu ao Senhor as palavras do povo,"},
{v:10,t:"o Senhor lhe disse: Vai ao povo e santifica-o hoje e amanhã; que lavem as suas roupas"},
{v:11,t:"e estejam prontos para o terceiro dia, porque no terceiro dia o Senhor descerá à vista de todo o povo sobre o monte Sinai."},
{v:12,t:"Marcarás um limite para o povo ao redor da montanha e dirás: Guardai-vos de subir à montanha e de tocar o seu sopé; todo aquele que tocar a montanha será morto."},
{v:13,t:"Ninguém porá a mão nele: será apedrejado ou flechado; seja animal, seja homem, não viverá. Quando soar a trombeta, então poderão subir à montanha."},
{v:14,t:"Moisés desceu da montanha para junto do povo e o santificou; e, depois que lavaram as suas roupas,"},
{v:15,t:"disse ao povo: Estai prontos para o terceiro dia; não vos aproximeis de mulher."},
{v:16,t:"Ao amanhecer do terceiro dia, houve trovões e relâmpagos, uma nuvem espessa cobriu a montanha, e o som da trombeta era fortíssimo; e todo o povo que estava no acampamento tremeu.",np:1},
{v:17,t:"Moisés fez o povo sair do acampamento ao encontro de Deus, e eles ficaram ao pé da montanha."},
{v:18,t:"Todo o monte Sinai fumegava, porque o Senhor tinha descido sobre ele no fogo; a fumaça subia como a de uma fornalha, e toda a montanha tremia violentamente."},
{v:19,t:"O som da trombeta ia ficando cada vez mais forte; Moisés falava, e Deus lhe respondia com o trovão.",n:"Com o trovão: em hebraico, com uma voz; a mesma palavra designa a voz e o trovão."},
{v:20,t:"O Senhor desceu sobre o monte Sinai, ao cume da montanha, e chamou Moisés ao cume. Moisés subiu,",np:1},
{v:21,t:"e o Senhor lhe disse: Desce e adverte o povo que não ultrapasse o limite para ver o Senhor, para que não pereçam muitos deles."},
{v:22,t:"Também os sacerdotes, que se aproximam do Senhor, devem santificar-se, para que o Senhor não os fira."},
{v:23,t:"Moisés disse ao Senhor: O povo não poderá subir ao monte Sinai, porque tu mesmo nos advertiste, dizendo: Marca um limite ao redor da montanha e santifica-a."},
{v:24,t:"O Senhor lhe disse: Vai, desce; depois subirás tu, e Aarão contigo; mas os sacerdotes e o povo não ultrapassem o limite para subir até o Senhor, para que ele não os fira."},
{v:25,t:"Moisés desceu para junto do povo e lhes disse tudo isso."}
];

window.TEXTOS_SEED["exodo"][20] = [
{s:"Os Dez Mandamentos"},
{v:1,t:"Então Deus pronunciou todas estas palavras:",n:"As dez palavras, o Decálogo, reaparecem com pequenas diferenças em Deuteronômio 5,6–21. A divisão dos mandamentos varia entre as tradições; a catequese católica segue a de Santo Agostinho."},
{v:2,t:"Eu sou o Senhor, teu Deus, que te tirei da terra do Egito, da casa da servidão.",n:"A lei começa por lembrar a libertação: os mandamentos são o modo de viver de um povo que Deus tirou da escravidão."},
{v:3,t:"Não terás outros deuses diante de mim.",np:1},
{v:4,t:"Não farás para ti imagem esculpida, nem figura alguma do que há em cima no céu, embaixo na terra ou nas águas debaixo da terra."},
{v:5,t:"Não te prostrarás diante delas nem lhes prestarás culto, porque eu, o Senhor, teu Deus, sou um Deus zeloso, que castigo a iniquidade dos pais nos filhos até a terceira e a quarta geração dos que me odeiam,"},
{v:6,t:"mas uso de misericórdia até mil gerações com os que me amam e guardam os meus mandamentos."},
{v:7,t:"Não tomarás em vão o nome do Senhor, teu Deus, porque o Senhor não deixará sem castigo quem tomar o seu nome em vão.",np:1},
{v:8,t:"Lembra-te do dia de sábado, para santificá-lo.",np:1},
{v:9,t:"Seis dias trabalharás e farás todas as tuas obras;"},
{v:10,t:"mas o sétimo dia é sábado do Senhor, teu Deus: não farás nele nenhum trabalho, nem tu, nem o teu filho, nem a tua filha, nem o teu servo, nem a tua serva, nem o teu animal, nem o estrangeiro que está dentro das tuas portas."},
{v:11,t:"Pois em seis dias o Senhor fez o céu, a terra, o mar e tudo o que neles existe, e no sétimo dia descansou; por isso o Senhor abençoou o dia de sábado e o santificou.",n:"Aqui o sábado se funda no descanso da criação (Gênesis 2,2–3); em Deuteronômio 5,15, na libertação do Egito."},
{v:12,t:"Honra teu pai e tua mãe, para que se prolonguem os teus dias na terra que o Senhor, teu Deus, te dá.",np:1},
{v:13,t:"Não matarás.",np:1},
{v:14,t:"Não cometerás adultério.",np:1},
{v:15,t:"Não furtarás.",np:1},
{v:16,t:"Não dirás falso testemunho contra o teu próximo.",np:1},
{v:17,t:"Não cobiçarás a casa do teu próximo: não desejarás a sua mulher, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma que lhe pertença.",np:1},
{s:"O povo diante de Deus"},
{v:18,t:"Todo o povo percebia os trovões e os relâmpagos, o som da trombeta e a montanha fumegante; e, cheios de medo e tremendo, ficaram de longe",n:"Percebia os trovões, à letra via as vozes: o texto mistura os sentidos para dizer o que não se pode dizer."},
{v:19,t:"e disseram a Moisés: Fala-nos tu, e nós ouviremos; mas que Deus não nos fale, para que não morramos."},
{v:20,t:"Moisés disse ao povo: Não tenhais medo, porque Deus veio para vos pôr à prova e para que o seu temor esteja diante de vós, a fim de que não pequeis.",np:1},
{v:21,t:"O povo ficou de longe, enquanto Moisés se aproximava da nuvem escura onde Deus estava."},
{s:"A lei sobre o altar"},
{v:22,t:"O Senhor disse a Moisés: Assim dirás aos filhos de Israel: Vós vistes que eu vos falei do céu.",n:"Começa aqui o Código da Aliança (20,22–23,33), a coleção de leis mais antiga de Israel."},
{v:23,t:"Não fareis deuses de prata ao meu lado, nem fareis para vós deuses de ouro."},
{v:24,t:"Farás para mim um altar de terra e sobre ele oferecerás os teus holocaustos e os teus sacrifícios de comunhão, as tuas ovelhas e os teus bois. Em todo lugar onde eu fizer lembrar o meu nome, virei a ti e te abençoarei."},
{v:25,t:"Se me fizeres um altar de pedra, não o construirás de pedras lavradas, porque, se passares o cinzel sobre ele, o profanarás."},
{v:26,t:"Não subirás por degraus ao meu altar, para que não se descubra a tua nudez."}
];

window.TEXTOS_SEED["exodo"][21] = [
{s:"Leis sobre os escravos"},
{v:1,t:"Estas são as normas que lhes proporás:"},
{v:2,t:"Se comprares um escravo hebreu, ele te servirá seis anos; no sétimo sairá livre, sem pagar nada.",n:"Nota do tradutor: as leis sobre a escravidão refletem a sociedade antiga, e o texto não foi suavizado; comparadas às leis dos povos vizinhos, porém, elas limitam o poder do senhor e protegem o escravo (21,20.26–27)."},
{v:3,t:"Se entrou sozinho, sairá sozinho; se tinha mulher, a mulher sairá com ele."},
{v:4,t:"Mas, se o seu senhor lhe deu uma mulher e ela lhe deu filhos ou filhas, a mulher e os filhos serão do senhor, e ele sairá sozinho."},
{v:5,t:"Mas, se o escravo disser: Amo o meu senhor, a minha mulher e os meus filhos; não quero sair livre,"},
{v:6,t:"o seu senhor o levará diante de Deus, o aproximará da porta ou do batente e lhe furará a orelha com uma sovela; e ele será seu escravo para sempre.",n:"Diante de Deus: talvez no santuário, ou diante dos juízes, que julgavam em nome de Deus."},
{v:7,t:"Se alguém vender a sua filha como serva, ela não sairá como saem os escravos.",np:1},
{v:8,t:"Se ela desagradar ao seu senhor, que a tinha destinado para si, ele a deixará resgatar; não terá o direito de vendê-la a estrangeiros, porque a enganou."},
{v:9,t:"Se a destinar ao seu filho, a tratará como se trata uma filha."},
{v:10,t:"Se tomar para si outra mulher, não diminuirá à primeira o alimento, a roupa e os direitos conjugais."},
{v:11,t:"Se não lhe der estas três coisas, ela sairá livre, sem pagar nada."},
{s:"Leis sobre a violência"},
{v:12,t:"Quem ferir um homem e causar a sua morte será morto."},
{v:13,t:"Mas, se não o fez de propósito, e Deus o deixou cair nas suas mãos, eu te indicarei um lugar para onde poderá fugir.",n:"As cidades de refúgio (Números 35,9–34; Deuteronômio 19,1–13)."},
{v:14,t:"Mas, se alguém matar o seu próximo de propósito e à traição, tu o arrancarás até do meu altar, para que morra.",n:"O altar dava asilo aos perseguidos (1 Reis 1,50–53), mas não ao assassino premeditado."},
{v:15,t:"Quem ferir o pai ou a mãe será morto.",np:1,n:"Nota do tradutor: a pena de morte aparece com frequência nestas leis antigas, e o texto não foi suavizado; ela exprime a gravidade que a comunidade atribuía a cada crime."},
{v:16,t:"Quem sequestrar uma pessoa, quer a tenha vendido, quer ela ainda esteja em seu poder, será morto.",np:1},
{v:17,t:"Quem amaldiçoar o pai ou a mãe será morto.",np:1,n:"Jesus cita este mandamento contra os que o anulam com as suas tradições (Mateus 15,4)."},
{v:18,t:"Se dois homens brigarem, e um ferir o outro com uma pedra ou com o punho, e este não morrer, mas tiver de ficar de cama,",np:1},
{v:19,t:"se ele se levantar e puder andar fora de casa apoiado no seu bastão, o que o feriu ficará sem castigo; só deverá pagar-lhe o tempo perdido e as despesas do tratamento."},
{v:20,t:"Se alguém bater com um bastão no seu escravo ou na sua escrava, e estes morrerem nas suas mãos, será punido.",np:1},
{v:21,t:"Mas, se sobreviverem um ou dois dias, não será punido, porque se trata do seu dinheiro."},
{v:22,t:"Se alguns homens brigarem e ferirem uma mulher grávida, e ela abortar sem que haja outro dano, o culpado pagará a indenização que o marido da mulher exigir e os juízes determinarem.",np:1},
{v:23,t:"Mas, se houver outro dano, pagarás vida por vida,"},
{v:24,t:"olho por olho, dente por dente, mão por mão, pé por pé,"},
{v:25,t:"queimadura por queimadura, ferida por ferida, golpe por golpe.",n:"A lei de talião limitava a vingança à medida do dano; na prática, era aplicada com indenizações. Jesus a supera com o mandamento de não revidar (Mateus 5,38–42)."},
{v:26,t:"Se alguém ferir o olho do seu escravo ou da sua escrava e o cegar, deverá deixá-lo livre em compensação pelo olho."},
{v:27,t:"E, se lhe fizer cair um dente, deverá deixá-lo livre em compensação pelo dente."},
{s:"Leis sobre os animais e os danos"},
{v:28,t:"Se um boi chifrar um homem ou uma mulher e causar a sua morte, o boi será apedrejado e a sua carne não será comida; mas o dono do boi não será culpado."},
{v:29,t:"Mas, se o boi já costumava chifrar, e o seu dono, avisado, não o prendeu, e o boi matar um homem ou uma mulher, o boi será apedrejado, e também o seu dono será morto.",np:1},
{v:30,t:"Se lhe impuserem um resgate, ele pagará pela sua vida tudo o que lhe for exigido."},
{v:31,t:"Se o boi chifrar um menino ou uma menina, será aplicada a mesma norma."},
{v:32,t:"Se o boi chifrar um escravo ou uma escrava, o dono pagará ao senhor deles trinta siclos de prata, e o boi será apedrejado."},
{v:33,t:"Se alguém abrir uma cisterna, ou cavar uma, e não a cobrir, e nela cair um boi ou um jumento,",np:1},
{v:34,t:"o dono da cisterna pagará o valor do animal ao seu dono, e o animal morto será dele."},
{v:35,t:"Se o boi de alguém ferir o boi de outro e causar a sua morte, venderão o boi vivo e repartirão o preço; e repartirão também o boi morto.",np:1},
{v:36,t:"Mas, se se sabia que o boi já costumava chifrar, e o dono não o prendeu, ele pagará boi por boi, e o boi morto será dele.",np:1},
{v:37,t:"Se alguém roubar um boi ou uma ovelha, e o abater ou vender, restituirá cinco bois pelo boi e quatro ovelhas pela ovelha.",n:"Em outras Bíblias, 21,37 é 22,1, e a numeração do capítulo 22 aumenta de uma unidade."}
];

window.TEXTOS_SEED["exodo"][22] = [
{s:"Leis sobre o roubo e os bens confiados"},
{v:1,t:"Se um ladrão for surpreendido arrombando uma casa e for ferido de morte, quem o feriu não será culpado de sangue."},
{v:2,t:"Mas, se o fato acontecer depois do nascer do sol, será culpado de sangue. O ladrão deverá restituir tudo; se não tiver com que pagar, será vendido para pagar o roubo.",n:"De noite, o morador não pode saber se o ladrão vem para matar; de dia, pode defender-se sem matar."},
{v:3,t:"Se o animal roubado, boi, jumento ou ovelha, for encontrado vivo em seu poder, restituirá o dobro."},
{v:4,t:"Se alguém soltar o seu gado para pastar num campo ou numa vinha, e o deixar pastar no campo de outro, restituirá plenamente com o produto do seu próprio campo, segundo a colheita; e, se o campo tiver sido todo devastado, restituirá com o melhor que tiver no seu campo ou na sua vinha.",np:1},
{v:5,t:"Se um fogo se espalhar e atingir os espinheiros e queimar os feixes, o trigo ainda em pé ou o campo, quem acendeu o fogo pagará o dano.",np:1},
{v:6,t:"Se alguém confiar ao seu próximo dinheiro ou objetos para guardar, e forem roubados da casa deste, o ladrão, se for encontrado, restituirá o dobro.",np:1},
{v:7,t:"Se o ladrão não for encontrado, o dono da casa comparecerá diante de Deus e jurará que não pôs a mão nos bens do seu próximo."},
{v:8,t:"Em toda questão de apropriação indevida, seja de boi, de jumento, de ovelha, de roupa ou de qualquer coisa perdida que alguém afirme ser sua, a causa das duas partes será levada diante de Deus, e aquele que Deus condenar restituirá o dobro ao seu próximo.",np:1},
{v:9,t:"Se alguém confiar ao seu próximo um jumento, um boi, uma ovelha ou qualquer outro animal para guardar, e o animal morrer, se ferir ou for levado por inimigos, sem que ninguém o veja,",np:1},
{v:10,t:"haverá entre os dois um juramento pelo Senhor de que o guardião não pôs a mão nos bens do próximo; o dono aceitará o juramento, e o outro não terá de restituir."},
{v:11,t:"Mas, se o animal lhe tiver sido roubado, indenizará o dono;"},
{v:12,t:"se tiver sido despedaçado por uma fera, levará os restos como prova e não terá de restituir."},
{v:13,t:"Se alguém pedir emprestado ao seu próximo um animal, e este se ferir ou morrer na ausência do dono, deverá restituí-lo.",np:1},
{v:14,t:"Mas, se o dono estava presente, não restituirá. Se o animal foi alugado, o aluguel cobre o dano."},
{s:"Leis diversas"},
{v:15,t:"Se alguém seduzir uma virgem que não está prometida em casamento e se deitar com ela, pagará o dote e a tomará por mulher.",n:"Nota do tradutor: a lei reflete uma sociedade em que a filha estava sob a autoridade do pai, e o texto não foi suavizado; o dote compensava o prejuízo da família."},
{v:16,t:"Se o pai da moça se recusar a dá-la a ele, pagará em dinheiro o valor do dote das virgens."},
{v:17,t:"Não deixarás viver a feiticeira.",np:1,n:"Nota do tradutor: a lei é dura, e o texto não foi suavizado; ela pertence a um tempo em que a magia era vista como ameaça mortal à comunidade e à fé no único Deus."},
{v:18,t:"Quem se deitar com um animal será morto.",np:1},
{v:19,t:"Quem oferecer sacrifícios a outros deuses, e não somente ao Senhor, será morto.",np:1},
{v:20,t:"Não maltratarás o estrangeiro nem o oprimirás, porque vós fostes estrangeiros na terra do Egito.",np:1},
{v:21,t:"Não fareis mal a nenhuma viúva nem a nenhum órfão.",np:1},
{v:22,t:"Se lhes fizerdes mal, e eles clamarem a mim, eu ouvirei o seu clamor;"},
{v:23,t:"a minha ira se acenderá, e eu vos matarei pela espada; e as vossas mulheres ficarão viúvas, e os vossos filhos, órfãos."},
{v:24,t:"Se emprestares dinheiro a alguém do meu povo, ao pobre que vive contigo, não agirás com ele como um credor: não lhe cobrareis juros.",np:1},
{v:25,t:"Se tomares em penhor o manto do teu próximo, tu o devolverás antes do pôr do sol;",np:1},
{v:26,t:"porque é a única coberta que ele tem, é o manto do seu corpo: com que dormirá? Se ele clamar a mim, eu o ouvirei, porque sou misericordioso."},
{v:27,t:"Não blasfemarás contra Deus e não amaldiçoarás o chefe do teu povo.",np:1,n:"São Paulo cita a segunda parte deste versículo diante do sumo sacerdote (Atos 23,5)."},
{v:28,t:"Não tardarás em oferecer as primícias da tua eira e do teu lagar. Tu me darás o primogênito dos teus filhos.",np:1},
{v:29,t:"Farás o mesmo com os teus bois e as tuas ovelhas: a cria ficará sete dias com a mãe, e no oitavo dia tu a darás a mim.",np:1},
{v:30,t:"Sereis para mim homens consagrados: não comereis carne de animal despedaçado no campo; vós a jogareis aos cães.",np:1}
];

window.TEXTOS_SEED["exodo"][23] = [
{s:"Justiça para todos"},
{v:1,t:"Não espalharás boatos falsos nem te aliarás ao ímpio para dar falso testemunho."},
{v:2,t:"Não seguirás a multidão para fazer o mal; e, num processo, não te deixarás levar pela maioria, desviando-te da verdade.",np:1},
{v:3,t:"Também não favorecerás o pobre no seu processo.",np:1,n:"A justiça não se deixa torcer nem pelo poder do rico nem pela compaixão pelo pobre (compare Levítico 19,15)."},
{v:4,t:"Se encontrares o boi ou o jumento do teu inimigo extraviado, tu o levarás de volta a ele.",np:1},
{v:5,t:"Se vires o jumento de quem te odeia caído debaixo da carga, não passarás adiante, mas o ajudarás a levantá-lo.",np:1},
{v:6,t:"Não torcerás o direito do pobre no seu processo.",np:1},
{v:7,t:"Foge da mentira. Não farás morrer o inocente e o justo, porque eu abomino o ímpio.",np:1},
{v:8,t:"Não aceitarás suborno, porque o suborno cega até os que veem claro e perverte as palavras dos justos.",np:1},
{v:9,t:"Não oprimirás o estrangeiro: vós sabeis o que sente o estrangeiro, porque vós mesmos fostes estrangeiros na terra do Egito.",np:1},
{s:"O ano sabático e o sábado"},
{v:10,t:"Durante seis anos semearás a tua terra e recolherás os seus produtos;"},
{v:11,t:"mas no sétimo ano a deixarás descansar, sem cultivá-la, para que os pobres do teu povo comam dela, e o que sobrar, comam-no os animais do campo. Farás o mesmo com a tua vinha e com o teu olival."},
{v:12,t:"Durante seis dias farás o teu trabalho; mas no sétimo dia descansarás, para que descansem o teu boi e o teu jumento, e tomem fôlego o filho da tua serva e o estrangeiro.",np:1},
{v:13,t:"Observai tudo o que vos disse; não invocareis o nome de outros deuses: que ele não se ouça da tua boca.",np:1},
{s:"As três festas anuais"},
{v:14,t:"Três vezes por ano celebrareis uma festa em minha honra."},
{v:15,t:"Observarás a festa dos Ázimos: durante sete dias comerás pães sem fermento, como te ordenei, no tempo marcado do mês de Abib, porque foi nele que saíste do Egito. Ninguém se apresentará diante de mim de mãos vazias.",np:1},
{v:16,t:"Observarás também a festa da Colheita, das primícias dos teus trabalhos, do que tiveres semeado no campo; e a festa da Recolha, no fim do ano, quando recolheres do campo todos os teus produtos.",np:1,n:"A festa da Colheita será chamada festa das Semanas, ou Pentecostes; a festa da Recolha, festa das Tendas (Levítico 23; Deuteronômio 16)."},
{v:17,t:"Três vezes por ano, todos os teus homens se apresentarão diante do Senhor Deus.",np:1},
{v:18,t:"Não oferecerás o sangue do meu sacrifício com pão fermentado, e a gordura da minha festa não ficará até a manhã seguinte.",np:1},
{v:19,t:"Levarás à casa do Senhor, teu Deus, as primícias dos primeiros frutos da tua terra. Não cozinharás o cabrito no leite da sua mãe.",np:1,n:"Talvez a proibição de um rito cananeu. A tradição judaica tirou daqui a separação entre carne e leite na alimentação."},
{s:"O anjo que guia o povo"},
{v:20,t:"Eis que envio um anjo à tua frente, para te guardar no caminho e te conduzir ao lugar que preparei."},
{v:21,t:"Respeita-o e ouve a sua voz; não lhe resistas, porque ele não perdoará as vossas transgressões, pois o meu nome está nele."},
{v:22,t:"Mas, se ouvires a sua voz e fizeres tudo o que eu disser, serei inimigo dos teus inimigos e adversário dos teus adversários."},
{v:23,t:"O meu anjo irá à tua frente e te introduzirá na terra dos amorreus, dos heteus, dos ferezeus, dos cananeus, dos heveus e dos jebuseus, e eu os exterminarei.",np:1},
{v:24,t:"Não te prostrarás diante dos seus deuses nem lhes prestarás culto; não imitarás as suas práticas, mas destruirás esses deuses e quebrarás as suas estelas.",n:"Nota do tradutor: a ordem de destruir os povos de Canaã e os seus cultos é das mais duras da Bíblia, e o texto não foi suavizado; ela visa sobretudo preservar Israel da idolatria (23,33)."},
{v:25,t:"Servireis ao Senhor, vosso Deus, e ele abençoará o teu pão e a tua água, e afastarei do meio de ti as doenças.",np:1},
{v:26,t:"Na tua terra não haverá mulher que aborte nem estéril; farei que chegues ao número completo dos teus dias."},
{v:27,t:"Mandarei à tua frente o meu terror e lançarei na confusão todos os povos em cujo território entrares; e farei que todos os teus inimigos te deem as costas,",np:1},
{v:28,t:"mandando à tua frente vespas, que expulsarão os heveus, os cananeus e os heteus diante de ti.",n:"Vespas: talvez imagem do pânico que o Senhor espalha entre os inimigos."},
{v:29,t:"Não os expulsarei da tua presença num só ano, para que a terra não se torne deserta e os animais selvagens não se multipliquem contra ti."},
{v:30,t:"Eu os expulsarei aos poucos da tua presença, até que te multipliques e tomes posse da terra."},
{v:31,t:"Fixarei as tuas fronteiras desde o mar Vermelho até o mar dos filisteus, e desde o deserto até o Rio; entregarei nas vossas mãos os habitantes da terra, e eu os expulsarei da vossa presença.",n:"O mar dos filisteus: o Mediterrâneo. O Rio: o Eufrates."},
{v:32,t:"Não farás aliança com eles nem com os seus deuses."},
{v:33,t:"Eles não habitarão na tua terra, para que não te façam pecar contra mim, servindo aos seus deuses; pois isso seria para ti uma armadilha."}
];

window.TEXTOS_SEED["exodo"][24] = [
{s:"A aliança selada com sangue"},
{v:1,t:"Deus disse a Moisés: Sobe até o Senhor, tu e Aarão, Nadab e Abiú e setenta dos anciãos de Israel, e prostrai-vos de longe."},
{v:2,t:"Só Moisés se aproximará do Senhor; os outros não se aproximarão, e o povo não subirá com ele."},
{v:3,t:"Moisés veio e contou ao povo todas as palavras do Senhor e todas as normas; e todo o povo respondeu a uma só voz: Faremos tudo o que o Senhor disse.",np:1},
{v:4,t:"Moisés escreveu todas as palavras do Senhor. Levantou-se de manhã cedo, construiu um altar ao pé da montanha e ergueu doze estelas, pelas doze tribos de Israel."},
{v:5,t:"Depois mandou alguns jovens dos filhos de Israel oferecer holocaustos e imolar novilhos ao Senhor como sacrifícios de comunhão."},
{v:6,t:"Moisés tomou metade do sangue e o pôs em bacias, e com a outra metade aspergiu o altar."},
{v:7,t:"Tomou o livro da aliança e o leu diante do povo, que respondeu: Faremos tudo o que o Senhor disse e obedeceremos."},
{v:8,t:"Então Moisés tomou o sangue, aspergiu com ele o povo e disse: Este é o sangue da aliança que o Senhor fez convosco, segundo todas estas palavras.",n:"O sangue une o altar, que representa Deus, e o povo: uma só vida os liga. Jesus retoma estas palavras na última ceia: Este é o meu sangue, o sangue da aliança (Marcos 14,24; compare Hebreus 9,18–22)."},
{s:"A refeição diante de Deus"},
{v:9,t:"Moisés subiu com Aarão, Nadab, Abiú e setenta dos anciãos de Israel."},
{v:10,t:"Eles viram o Deus de Israel; debaixo dos seus pés havia como um pavimento de safira, límpido como o próprio céu.",n:"Nota do tradutor: o texto diz que viram Deus, sem descrevê-lo; só fala do que estava debaixo dos seus pés. A tradução grega atenuou: viram o lugar onde estava o Deus de Israel. Aqui o texto não foi suavizado."},
{v:11,t:"Ele não estendeu a mão contra esses escolhidos dos filhos de Israel: eles viram a Deus, comeram e beberam."},
{s:"Moisés sobe à montanha"},
{v:12,t:"O Senhor disse a Moisés: Sobe até mim, na montanha, e fica lá; eu te darei as tábuas de pedra, a lei e os mandamentos que escrevi para os instruir."},
{v:13,t:"Moisés se levantou com Josué, o seu ajudante; e, antes de subir à montanha de Deus,"},
{v:14,t:"disse aos anciãos: Esperai-nos aqui, até voltarmos a vós. Aarão e Hur estão convosco; quem tiver alguma questão, dirija-se a eles."},
{v:15,t:"Moisés subiu à montanha, e a nuvem cobriu a montanha.",np:1},
{v:16,t:"A glória do Senhor pousou sobre o monte Sinai, e a nuvem o cobriu durante seis dias; no sétimo dia, o Senhor chamou Moisés do meio da nuvem."},
{v:17,t:"A glória do Senhor aparecia aos olhos dos filhos de Israel como um fogo devorador no cume da montanha."},
{v:18,t:"Moisés entrou no meio da nuvem e subiu à montanha; e ficou na montanha quarenta dias e quarenta noites."}
];

window.TEXTOS_SEED["exodo"][25] = [
{s:"As ofertas para o santuário"},
{v:1,t:"O Senhor falou a Moisés e disse:"},
{v:2,t:"Dize aos filhos de Israel que me tragam uma oferta; recebereis a minha oferta de todo aquele que a der de coração generoso.",n:"Os capítulos 25–31 contêm as instruções para o santuário do deserto; os capítulos 35–40 contam a sua execução, quase com as mesmas palavras."},
{v:3,t:"Eis a oferta que recebereis deles: ouro, prata e bronze;",np:1},
{v:4,t:"púrpura violeta, púrpura escarlate, carmesim, linho fino e pelo de cabra;"},
{v:5,t:"peles de carneiro tingidas de vermelho, peles finas e madeira de acácia;",n:"Peles finas: a Nova Vulgata diz peles de golfinho; o sentido da palavra hebraica tahash é incerto (compare Números 4,6)."},
{v:6,t:"azeite para a iluminação, aromas para o óleo da unção e para o incenso perfumado;"},
{v:7,t:"pedras de ônix e outras pedras para engastar no efod e no peitoral."},
{v:8,t:"Eles me farão um santuário, e eu habitarei no meio deles.",n:"Habitarei no meio deles: o centro de todas estas instruções. São João dirá do Verbo que armou a sua tenda entre nós (João 1,14)."},
{v:9,t:"Fareis tudo segundo o modelo do tabernáculo e de todos os seus utensílios que eu te vou mostrar."},
{s:"A arca"},
{v:10,t:"Farão uma arca de madeira de acácia, de dois côvados e meio de comprimento, um côvado e meio de largura e um côvado e meio de altura.",n:"O côvado media cerca de meio metro: a arca tinha pouco mais de um metro de comprimento."},
{v:11,t:"Tu a revestirás de ouro puro, por dentro e por fora, e farás ao redor dela uma moldura de ouro."},
{v:12,t:"Fundirás para ela quatro argolas de ouro, que porás nos seus quatro pés: duas argolas de um lado e duas do outro."},
{v:13,t:"Farás também varais de madeira de acácia e os revestirás de ouro;",np:1},
{v:14,t:"e os passarás pelas argolas dos lados da arca, para transportá-la."},
{v:15,t:"Os varais ficarão nas argolas da arca e nunca serão retirados."},
{v:16,t:"Porás na arca o Testemunho que eu te darei.",n:"O Testemunho: as tábuas da Lei (31,18)."},
{v:17,t:"Farás também um propiciatório de ouro puro, de dois côvados e meio de comprimento e um côvado e meio de largura.",np:1,n:"Propiciatório: a tampa da arca, lugar do perdão, onde o sumo sacerdote aspergia o sangue no dia da Expiação (Levítico 16,14–15). São Paulo aplica o termo a Cristo (Romanos 3,25)."},
{v:18,t:"Farás dois querubins de ouro batido nas duas extremidades do propiciatório,"},
{v:19,t:"um querubim numa extremidade e o outro na outra; farás os querubins formando uma só peça com o propiciatório, nas suas duas extremidades."},
{v:20,t:"Os querubins terão as asas estendidas para o alto, cobrindo com elas o propiciatório; estarão voltados um para o outro, com o rosto voltado para o propiciatório,"},
{v:21,t:"que servirá de tampa para a arca; e na arca porás o Testemunho que eu te darei."},
{v:22,t:"Ali me encontrarei contigo e, de cima do propiciatório, do meio dos dois querubins que estão sobre a arca do Testemunho, te comunicarei tudo o que te ordenar para os filhos de Israel."},
{s:"A mesa dos pães"},
{v:23,t:"Farás também uma mesa de madeira de acácia, de dois côvados de comprimento, um côvado de largura e um côvado e meio de altura."},
{v:24,t:"Tu a revestirás de ouro puro e farás ao redor dela uma moldura de ouro."},
{v:25,t:"Farás também ao redor dela um friso de quatro dedos de largura e, sobre o friso, uma moldura de ouro."},
{v:26,t:"Farás para ela quatro argolas de ouro e as porás nos quatro cantos, junto aos quatro pés."},
{v:27,t:"As argolas ficarão junto ao friso, para por elas passarem os varais que servirão para transportar a mesa."},
{v:28,t:"Farás os varais de madeira de acácia e os revestirás de ouro; com eles se transportará a mesa."},
{v:29,t:"Farás também os seus pratos, as suas taças, as suas jarras e as suas bacias para as libações; tu os farás de ouro puro."},
{v:30,t:"E porás sempre sobre a mesa, diante de mim, os pães da proposição.",n:"Pães da proposição: doze pães renovados a cada sábado, apresentados diante do Senhor (Levítico 24,5–9; compare Mateus 12,4)."},
{s:"O candelabro"},
{v:31,t:"Farás também um candelabro de ouro puro, trabalhado a martelo: a base, a haste, os cálices, os botões e as flores formarão uma só peça."},
{v:32,t:"Seis braços sairão dos seus lados: três braços de um lado e três do outro."},
{v:33,t:"Num braço haverá três cálices em forma de flor de amendoeira, com botão e flor; e no outro braço, três cálices em forma de flor de amendoeira, com botão e flor; assim serão os seis braços que saem do candelabro."},
{v:34,t:"Na própria haste do candelabro haverá quatro cálices em forma de flor de amendoeira, com os seus botões e as suas flores:"},
{v:35,t:"um botão debaixo de cada par de braços, nos três pares de braços que saem da haste."},
{v:36,t:"Os botões e os braços formarão uma só peça com o candelabro: tudo de ouro puro, trabalhado a martelo."},
{v:37,t:"Farás também as suas sete lâmpadas, que colocarás sobre ele, de modo que iluminem a frente."},
{v:38,t:"As suas tesouras de pavio e os seus pratinhos serão de ouro puro."},
{v:39,t:"Com um talento de ouro puro farás o candelabro e todos esses utensílios.",np:1,n:"Um talento pesava cerca de trinta quilos."},
{v:40,t:"Olha, e faze tudo segundo o modelo que te foi mostrado na montanha.",n:"A Carta aos Hebreus vê no santuário terrestre uma cópia do santuário celeste (Hebreus 8,5)."}
];

window.TEXTOS_SEED["exodo"][26] = [
{s:"O tabernáculo"},
{v:1,t:"Farás o tabernáculo com dez cortinas de linho fino retorcido, de púrpura violeta, de púrpura escarlate e de carmesim, com querubins bordados artisticamente."},
{v:2,t:"Cada cortina terá vinte e oito côvados de comprimento e quatro côvados de largura; todas as cortinas terão a mesma medida."},
{v:3,t:"Cinco cortinas serão unidas uma à outra, e as outras cinco também serão unidas da mesma forma."},
{v:4,t:"Farás laços de púrpura violeta na borda da última cortina do primeiro conjunto, e farás o mesmo na borda da última cortina do segundo conjunto."},
{v:5,t:"Farás cinquenta laços numa cortina e cinquenta laços na borda da cortina do segundo conjunto, de modo que os laços fiquem um diante do outro."},
{v:6,t:"Farás também cinquenta colchetes de ouro, com os quais unirás as cortinas uma à outra, para que o tabernáculo forme um todo."},
{v:7,t:"Farás também onze cortinas de pelo de cabra, para servirem de tenda sobre o tabernáculo.",np:1},
{v:8,t:"Cada cortina terá trinta côvados de comprimento e quatro côvados de largura; as onze cortinas terão a mesma medida."},
{v:9,t:"Unirás cinco cortinas de um lado e seis do outro, e dobrarás a sexta cortina na parte da frente da tenda."},
{v:10,t:"Farás cinquenta laços na borda da última cortina do primeiro conjunto e cinquenta laços na borda da cortina do segundo conjunto."},
{v:11,t:"Farás também cinquenta colchetes de bronze, que meterás nos laços, para unir a tenda, de modo que forme um todo."},
{v:12,t:"Quanto ao que sobrar das cortinas da tenda, a metade da cortina que sobra ficará pendente na parte de trás do tabernáculo;"},
{v:13,t:"e o côvado que sobra de um lado e o côvado que sobra do outro, no comprimento das cortinas da tenda, ficarão pendentes dos dois lados do tabernáculo, para cobri-lo."},
{v:14,t:"Farás também para a tenda uma cobertura de peles de carneiro tingidas de vermelho e, por cima dela, outra cobertura de peles finas.",np:1},
{s:"As tábuas e as travessas"},
{v:15,t:"Farás para o tabernáculo tábuas de madeira de acácia, postas de pé,"},
{v:16,t:"cada uma de dez côvados de comprimento e um côvado e meio de largura."},
{v:17,t:"Cada tábua terá dois encaixes, para se unir à outra; assim farás todas as tábuas do tabernáculo.",np:1},
{v:18,t:"Vinte delas estarão do lado sul, voltado para o meio-dia;"},
{v:19,t:"e farás quarenta bases de prata para as vinte tábuas, duas bases debaixo de cada tábua, para os seus dois encaixes."},
{v:20,t:"Para o outro lado do tabernáculo, o lado norte, haverá vinte tábuas,"},
{v:21,t:"com as suas quarenta bases de prata, duas bases debaixo de cada tábua."},
{v:22,t:"Para o fundo do tabernáculo, do lado do ocidente, farás seis tábuas;"},
{v:23,t:"e farás ainda duas tábuas para os cantos do fundo do tabernáculo."},
{v:24,t:"Elas serão duplas desde baixo até em cima, unidas por uma só argola; assim serão as duas, que formarão os dois cantos."},
{v:25,t:"Haverá, pois, oito tábuas com as suas bases de prata, dezesseis bases, duas debaixo de cada tábua."},
{v:26,t:"Farás também travessas de madeira de acácia: cinco para as tábuas de um lado do tabernáculo,",np:1},
{v:27,t:"cinco para as tábuas do outro lado, e cinco para as tábuas do fundo, do lado do ocidente."},
{v:28,t:"A travessa do meio passará pelo meio das tábuas, de uma extremidade à outra."},
{v:29,t:"Revestirás de ouro as tábuas e farás de ouro as argolas por onde passarão as travessas; e revestirás de ouro também as travessas."},
{v:30,t:"Levantarás o tabernáculo segundo o modelo que te foi mostrado na montanha."},
{s:"O véu"},
{v:31,t:"Farás também um véu de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido, com querubins bordados artisticamente."},
{v:32,t:"Tu o pendurarás em quatro colunas de acácia revestidas de ouro, com ganchos de ouro e bases de prata."},
{v:33,t:"Porás o véu debaixo dos colchetes, e ali, atrás do véu, colocarás a arca do Testemunho; o véu separará para vós o Santo do Santo dos Santos.",n:"O Santo dos Santos: o lugar mais sagrado, onde só o sumo sacerdote entrava, uma vez por ano. Na morte de Jesus, o véu do templo se rasgou (Marcos 15,38; compare Hebreus 10,19–20)."},
{v:34,t:"Porás o propiciatório sobre a arca do Testemunho, no Santo dos Santos,"},
{v:35,t:"e a mesa fora do véu; o candelabro, defronte da mesa, no lado sul do tabernáculo; e a mesa ficará no lado norte."},
{v:36,t:"Farás também para a entrada da tenda uma cortina de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido, obra de bordador.",np:1},
{v:37,t:"Para essa cortina farás cinco colunas de acácia, que revestirás de ouro, com ganchos de ouro; e fundirás para elas cinco bases de bronze."}
];

window.TEXTOS_SEED["exodo"][27] = [
{s:"O altar dos holocaustos"},
{v:1,t:"Farás também o altar de madeira de acácia, de cinco côvados de comprimento e cinco côvados de largura: o altar será quadrado; e terá três côvados de altura."},
{v:2,t:"Nos seus quatro cantos farás chifres, que formarão uma só peça com ele, e o revestirás de bronze."},
{v:3,t:"Farás também os seus recipientes para recolher as cinzas, as pás, as bacias, os garfos e os braseiros; farás de bronze todos os seus utensílios."},
{v:4,t:"Farás para ele uma grelha de bronze em forma de rede, e nos quatro cantos da rede farás quatro argolas de bronze,"},
{v:5,t:"e a porás debaixo da borda do altar, de modo que a rede chegue até a metade da altura do altar."},
{v:6,t:"Farás também varais para o altar, dois varais de madeira de acácia, que revestirás de bronze,"},
{v:7,t:"e os passarás pelas argolas; os varais ficarão dos dois lados do altar quando for transportado."},
{v:8,t:"Farás o altar oco, de tábuas; como te foi mostrado na montanha, assim o farão."},
{s:"O átrio"},
{v:9,t:"Farás também o átrio do tabernáculo. Do lado sul, voltado para o meio-dia, o átrio terá cortinas de linho fino retorcido, num comprimento de cem côvados para um lado,"},
{v:10,t:"com vinte colunas e as suas vinte bases de bronze; os ganchos das colunas e as suas vergas serão de prata.",n:"Vergas: hastes que ligavam as colunas; o sentido da palavra hebraica é discutido."},
{v:11,t:"Do mesmo modo, do lado norte haverá cortinas num comprimento de cem côvados, com vinte colunas e vinte bases de bronze; os ganchos das colunas e as suas vergas serão de prata."},
{v:12,t:"Na largura do átrio, do lado do ocidente, haverá cortinas num comprimento de cinquenta côvados, com dez colunas e dez bases."},
{v:13,t:"A largura do átrio, do lado do oriente, será de cinquenta côvados:"},
{v:14,t:"de um lado haverá quinze côvados de cortinas, com três colunas e três bases;"},
{v:15,t:"e do outro lado, quinze côvados de cortinas, com três colunas e três bases."},
{v:16,t:"Na entrada do átrio haverá uma cortina de vinte côvados, de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido, obra de bordador, com quatro colunas e quatro bases."},
{v:17,t:"Todas as colunas ao redor do átrio terão vergas de prata, ganchos de prata e bases de bronze."},
{v:18,t:"O átrio terá cem côvados de comprimento, cinquenta de largura e cinco côvados de altura; será de linho fino retorcido, e as bases serão de bronze."},
{v:19,t:"Todos os utensílios do tabernáculo, para todo o seu serviço, todas as suas estacas e todas as estacas do átrio serão de bronze."},
{s:"O azeite para o candelabro"},
{v:20,t:"Ordenarás aos filhos de Israel que te tragam azeite puro de oliva, extraído com pilão, para a iluminação, a fim de manter acesa continuamente uma lâmpada"},
{v:21,t:"na tenda do encontro, fora do véu que está diante do Testemunho. Aarão e os seus filhos a prepararão, para que arda diante do Senhor da tarde até a manhã. É uma lei perpétua para os filhos de Israel, de geração em geração.",n:"Tenda do encontro: o lugar onde Deus se encontra com Moisés e com o povo; é outro nome do tabernáculo."}
];

window.TEXTOS_SEED["exodo"][28] = [
{s:"As vestes sacerdotais"},
{v:1,t:"Faze vir para junto de ti, do meio dos filhos de Israel, o teu irmão Aarão e os seus filhos, para que exerçam o sacerdócio em minha honra: Aarão, Nadab, Abiú, Eleazar e Itamar."},
{v:2,t:"Farás para Aarão, teu irmão, vestes sagradas, para glória e ornamento.",np:1},
{v:3,t:"Falarás a todos os artesãos hábeis, que enchi de espírito de sabedoria, para que façam as vestes de Aarão, a fim de consagrá-lo para exercer o sacerdócio em minha honra."},
{v:4,t:"Estas são as vestes que farão: o peitoral, o efod, o manto, a túnica tecida, o turbante e o cíngulo. Farão vestes sagradas para Aarão, teu irmão, e para os seus filhos, para que exerçam o sacerdócio em minha honra;"},
{v:5,t:"e para isso usarão ouro, púrpura violeta, púrpura escarlate, carmesim e linho fino."},
{s:"O efod"},
{v:6,t:"Farão o efod de ouro, de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido, trabalhado artisticamente.",n:"Efod: veste sacerdotal em forma de avental ou colete, presa por ombreiras e por um cinto."},
{v:7,t:"Terá duas ombreiras presas às suas duas extremidades, para que se una."},
{v:8,t:"O cinto do efod, que vai por cima dele para o ajustar, será do mesmo trabalho e formará uma só peça com ele: de ouro, de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido."},
{v:9,t:"Tomarás duas pedras de ônix e gravarás nelas os nomes dos filhos de Israel:"},
{v:10,t:"seis nomes numa pedra e os outros seis na outra pedra, segundo a ordem do seu nascimento."},
{v:11,t:"Gravarás nas duas pedras os nomes dos filhos de Israel como faz o lapidador, como se grava um sinete, e as engastarás em filigrana de ouro."},
{v:12,t:"Porás as duas pedras sobre as ombreiras do efod, como pedras de memorial para os filhos de Israel; assim Aarão levará os nomes deles diante do Senhor sobre os seus dois ombros, como memorial."},
{v:13,t:"Farás também engastes de filigrana de ouro"},
{v:14,t:"e duas correntinhas de ouro puro, trançadas como cordões, e fixarás as correntinhas trançadas nos engastes."},
{s:"O peitoral"},
{v:15,t:"Farás também o peitoral do julgamento, trabalhado artisticamente, do mesmo trabalho que o efod: de ouro, de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido.",n:"Peitoral do julgamento: nele estavam o Urim e o Tumim, usados para conhecer a decisão de Deus (28,30)."},
{v:16,t:"Será quadrado e duplo, de um palmo de comprimento e um palmo de largura."},
{v:17,t:"Nele engastarás quatro fileiras de pedras: na primeira fileira, um sárdio, um topázio e uma esmeralda;",n:"A identificação destas pedras é incerta; seguem-se os nomes da Nova Vulgata."},
{v:18,t:"na segunda fileira, um carbúnculo, uma safira e um jaspe;"},
{v:19,t:"na terceira fileira, um jacinto, uma ágata e uma ametista;"},
{v:20,t:"na quarta fileira, um crisólito, um ônix e um berilo. Serão engastadas em ouro, cada uma no seu lugar."},
{v:21,t:"As pedras corresponderão aos nomes dos filhos de Israel: serão doze, segundo os seus nomes; cada uma terá gravado, como num sinete, o nome de uma das doze tribos.",n:"Compare as doze pedras dos alicerces da Jerusalém celeste (Apocalipse 21,19–20)."},
{v:22,t:"Farás para o peitoral correntinhas de ouro puro, trançadas como cordões;"},
{v:23,t:"e farás para o peitoral duas argolas de ouro, que porás nas duas extremidades superiores do peitoral;"},
{v:24,t:"prenderás as duas correntinhas de ouro às duas argolas, nas extremidades do peitoral,"},
{v:25,t:"e as outras duas pontas das correntinhas prenderás aos dois engastes, nas ombreiras do efod, na parte da frente."},
{v:26,t:"Farás também duas argolas de ouro e as porás nas duas extremidades inferiores do peitoral, na borda interior, voltada para o efod.",np:1},
{v:27,t:"Farás mais duas argolas de ouro e as porás na parte de baixo das duas ombreiras do efod, na frente, junto à costura, por cima do cinto do efod;"},
{v:28,t:"e o peitoral será preso pelas suas argolas às argolas do efod com um cordão de púrpura violeta, para que fique por cima do cinto do efod e não se separe do efod."},
{v:29,t:"Assim Aarão levará os nomes dos filhos de Israel no peitoral do julgamento, sobre o seu coração, quando entrar no santuário, como memorial perpétuo diante do Senhor."},
{v:30,t:"Porás no peitoral do julgamento o Urim e o Tumim, que estarão sobre o coração de Aarão quando ele entrar na presença do Senhor; e Aarão levará sempre sobre o seu coração o julgamento dos filhos de Israel diante do Senhor.",n:"Urim e Tumim: objetos usados para consultar a vontade de Deus, talvez por sorteio; o sentido exato dos nomes é incerto (compare Levítico 8,8; 1 Samuel 14,41)."},
{s:"O manto e a lâmina de ouro"},
{v:31,t:"Farás o manto do efod todo de púrpura violeta,"},
{v:32,t:"com uma abertura para a cabeça no meio; essa abertura terá ao redor uma borda tecida, como a abertura de uma couraça, para que não se rasgue."},
{v:33,t:"Na orla inferior do manto, ao redor, farás romãs de púrpura violeta, de púrpura escarlate e de carmesim, e entre elas, ao redor, campainhas de ouro:"},
{v:34,t:"uma campainha de ouro e uma romã, uma campainha de ouro e uma romã, ao redor de toda a orla do manto."},
{v:35,t:"Aarão o vestirá para exercer o seu ministério, e o som das campainhas será ouvido quando ele entrar no santuário, diante do Senhor, e quando sair, para que não morra."},
{v:36,t:"Farás também uma lâmina de ouro puro, na qual gravarás, como se grava um sinete: Consagrado ao Senhor.",np:1},
{v:37,t:"Tu a prenderás com um cordão de púrpura violeta, e ela ficará sobre o turbante,"},
{v:38,t:"na testa de Aarão. Aarão levará as faltas cometidas nas coisas sagradas que os filhos de Israel consagrarem em todas as suas ofertas; a lâmina estará sempre na sua testa, para que eles sejam aceitos diante do Senhor."},
{v:39,t:"Tecerás a túnica de linho fino, farás o turbante de linho fino e farás o cíngulo, obra de bordador.",np:1},
{v:40,t:"Para os filhos de Aarão farás túnicas, cíngulos e mitras, para glória e ornamento.",np:1},
{v:41,t:"Com estas vestes vestirás Aarão, teu irmão, e os seus filhos com ele; tu os ungirás, os investirás e os consagrarás, para que exerçam o sacerdócio em minha honra.",n:"Investir: à letra, encher as mãos, expressão que designa a posse no cargo sacerdotal (compare 29,9)."},
{v:42,t:"Farás também para eles calções de linho, para cobrir a sua nudez, da cintura até as coxas."},
{v:43,t:"Aarão e os seus filhos os usarão quando entrarem na tenda do encontro ou quando se aproximarem do altar para servir no santuário, para que não incorram em culpa e morram. É uma lei perpétua para ele e para a sua descendência depois dele."}
];

window.TEXTOS_SEED["exodo"][29] = [
{s:"A consagração dos sacerdotes"},
{v:1,t:"Eis o que farás para consagrá-los ao meu sacerdócio: toma um novilho e dois carneiros sem defeito,",n:"O rito aqui prescrito será executado em Levítico 8."},
{v:2,t:"pães ázimos, bolos sem fermento amassados com azeite e obreias sem fermento untadas com azeite; tu os farás de flor de farinha de trigo,"},
{v:3,t:"os porás num cesto e os oferecerás no cesto, com o novilho e os dois carneiros."},
{v:4,t:"Farás Aarão e os seus filhos aproximarem-se da entrada da tenda do encontro e, depois de lavá-los com água,"},
{v:5,t:"vestirás Aarão com as suas vestes: a túnica, o manto do efod, o efod e o peitoral, e o cingirás com o cinto do efod;"},
{v:6,t:"porás o turbante na sua cabeça e, sobre o turbante, o diadema sagrado;"},
{v:7,t:"tomarás o óleo da unção e o derramarás sobre a sua cabeça: assim será consagrado."},
{v:8,t:"Depois farás os seus filhos aproximarem-se, os vestirás com as túnicas de linho, os cingirás com os cíngulos"},
{v:9,t:"e lhes porás as mitras; e o sacerdócio lhes pertencerá por lei perpétua. Depois de teres investido Aarão e os seus filhos,"},
{v:10,t:"farás trazer o novilho diante da tenda do encontro; Aarão e os seus filhos porão as mãos sobre a cabeça do novilho,"},
{v:11,t:"e tu imolarás o novilho diante do Senhor, à entrada da tenda do encontro."},
{v:12,t:"Tomarás do sangue do novilho e com o dedo o porás sobre os chifres do altar; e derramarás todo o resto do sangue ao pé do altar.",np:1},
{v:13,t:"Tomarás toda a gordura que envolve as entranhas, o lóbulo do fígado, os dois rins e a gordura que está sobre eles, e os queimarás sobre o altar."},
{v:14,t:"Mas a carne do novilho, o couro e os excrementos, tu os queimarás no fogo fora do acampamento: é um sacrifício pelo pecado.",n:"Compare Hebreus 13,11–12: Jesus sofreu fora da porta da cidade."},
{v:15,t:"Tomarás depois um dos carneiros, e Aarão e os seus filhos porão as mãos sobre a sua cabeça;",np:1},
{v:16,t:"e, depois de imolá-lo, tomarás o seu sangue e o derramarás sobre o altar, ao redor."},
{v:17,t:"Cortarás o carneiro em pedaços, lavarás as suas entranhas e as suas pernas e as porás sobre os pedaços e sobre a cabeça."},
{v:18,t:"E queimarás o carneiro inteiro sobre o altar: é um holocausto para o Senhor, um aroma agradável, uma oferta queimada para o Senhor."},
{v:19,t:"Tomarás depois o outro carneiro, e Aarão e os seus filhos porão as mãos sobre a sua cabeça;",np:1},
{v:20,t:"e, depois de imolá-lo, tomarás do seu sangue e o porás sobre o lóbulo da orelha direita de Aarão e dos seus filhos, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito; e derramarás o sangue sobre o altar, ao redor.",n:"A orelha, a mão e o pé: o sacerdote é consagrado para ouvir, agir e caminhar segundo Deus."},
{v:21,t:"Tomarás do sangue que está sobre o altar e do óleo da unção e aspergirás Aarão e as suas vestes, e os seus filhos e as vestes dos seus filhos com ele. Assim ficarão consagrados ele e as suas vestes, os seus filhos e as vestes dos seus filhos com ele."},
{v:22,t:"Tomarás a gordura do carneiro, a cauda, a gordura que envolve as entranhas, o lóbulo do fígado, os dois rins e a gordura que está sobre eles, e a coxa direita, porque é o carneiro da investidura;",np:1},
{v:23,t:"tomarás também um pão, um bolo de pão com azeite e uma obreia do cesto dos ázimos, que está diante do Senhor;"},
{v:24,t:"porás tudo isso nas mãos de Aarão e nas mãos dos seus filhos, e eles o moverão com um gesto para a frente e para trás, como oferenda movida diante do Senhor.",n:"Oferenda movida: gesto de apresentação a Deus, com um movimento para a frente e para trás."},
{v:25,t:"Depois o receberás das mãos deles e o queimarás sobre o altar, em cima do holocausto, como aroma agradável diante do Senhor: é uma oferta queimada para o Senhor."},
{v:26,t:"Tomarás o peito do carneiro da investidura de Aarão e o moverás como oferenda movida diante do Senhor; e ele será a tua porção."},
{v:27,t:"Consagrarás o peito da oferenda movida e a coxa da oferenda elevada, a parte que foi movida e a que foi elevada do carneiro",np:1},
{v:28,t:"da investidura de Aarão e dos seus filhos; pertencerão a Aarão e aos seus filhos, por lei perpétua, da parte dos filhos de Israel, porque é uma oferta elevada, tirada dos sacrifícios de comunhão dos filhos de Israel: é a oferta que eles elevam ao Senhor."},
{v:29,t:"As vestes sagradas de Aarão passarão depois dele aos seus filhos, que as usarão quando forem ungidos e investidos.",np:1},
{v:30,t:"Aquele dos seus filhos que for sacerdote no seu lugar e entrar na tenda do encontro para servir no santuário as vestirá durante sete dias."},
{v:31,t:"Tomarás o carneiro da investidura e cozinharás a sua carne num lugar santo.",np:1},
{v:32,t:"Aarão e os seus filhos comerão a carne do carneiro e o pão que está no cesto, à entrada da tenda do encontro.",np:1},
{v:33,t:"Comerão aquilo com que se fez a expiação, na sua investidura e consagração; nenhum estranho comerá disso, porque são coisas santas."},
{v:34,t:"Se sobrar alguma coisa da carne da investidura ou do pão até a manhã seguinte, queimarás no fogo o que sobrar; não se comerá, porque é coisa santa."},
{v:35,t:"Farás assim com Aarão e com os seus filhos, conforme tudo o que te ordenei. Durante sete dias os investirás,",np:1},
{v:36,t:"e cada dia oferecerás um novilho em sacrifício pelo pecado, pela expiação; purificarás o altar fazendo a expiação sobre ele e o ungirás para consagrá-lo."},
{v:37,t:"Durante sete dias farás a expiação pelo altar e o consagrarás; e o altar será santíssimo: tudo o que tocar o altar ficará consagrado."},
{s:"O sacrifício perpétuo"},
{v:38,t:"Eis o que oferecerás sobre o altar: dois cordeiros de um ano, cada dia, continuamente,"},
{v:39,t:"um cordeiro de manhã e o outro ao entardecer;"},
{v:40,t:"com o primeiro cordeiro, a décima parte de um efá de flor de farinha amassada com a quarta parte de um hin de azeite de oliva batida, e, como libação, a quarta parte de um hin de vinho.",n:"O hin media uns seis litros."},
{v:41,t:"O outro cordeiro oferecerás ao entardecer, com a mesma oferta e a mesma libação da manhã, como aroma agradável, oferta queimada para o Senhor:"},
{v:42,t:"é o holocausto perpétuo, de geração em geração, à entrada da tenda do encontro, diante do Senhor, onde me encontrarei convosco para falar contigo."},
{v:43,t:"Ali me encontrarei com os filhos de Israel, e o lugar será santificado pela minha glória.",np:1},
{v:44,t:"Consagrarei a tenda do encontro e o altar; consagrarei também Aarão e os seus filhos, para que exerçam o sacerdócio em minha honra."},
{v:45,t:"Habitarei no meio dos filhos de Israel e serei o seu Deus;"},
{v:46,t:"e eles saberão que eu sou o Senhor, seu Deus, que os tirei da terra do Egito para habitar no meio deles: eu, o Senhor, seu Deus."}
];

window.TEXTOS_SEED["exodo"][30] = [
{s:"O altar do incenso"},
{v:1,t:"Farás também um altar para queimar o incenso; tu o farás de madeira de acácia,"},
{v:2,t:"de um côvado de comprimento e um côvado de largura: será quadrado; e terá dois côvados de altura; os seus chifres formarão uma só peça com ele."},
{v:3,t:"Tu o revestirás de ouro puro, a parte de cima, os lados ao redor e os chifres; e farás ao redor dele uma moldura de ouro,"},
{v:4,t:"e duas argolas de ouro debaixo da moldura, dos dois lados, para nelas passarem os varais com que será transportado."},
{v:5,t:"Farás os varais de madeira de acácia e os revestirás de ouro."},
{v:6,t:"Porás o altar diante do véu que está em frente da arca do Testemunho, diante do propiciatório que está sobre o Testemunho, onde me encontrarei contigo."},
{v:7,t:"Aarão queimará sobre ele o incenso aromático; todas as manhãs, quando preparar as lâmpadas, o queimará;"},
{v:8,t:"e, quando acender as lâmpadas ao entardecer, também o queimará: será um incenso perpétuo diante do Senhor, de geração em geração.",n:"Zacarias oferecia o incenso quando o anjo lhe apareceu (Lucas 1,8–11). O incenso se tornou imagem da oração que sobe a Deus (Salmo 141,2; Apocalipse 8,3–4)."},
{v:9,t:"Não oferecereis sobre ele incenso profano, nem holocausto, nem oferta, e não derramareis sobre ele libação alguma."},
{v:10,t:"Uma vez por ano, Aarão fará a expiação sobre os chifres do altar com o sangue do sacrifício pelo pecado; uma vez por ano se fará sobre ele a expiação, de geração em geração: será santíssimo para o Senhor."},
{s:"O resgate das vidas"},
{v:11,t:"O Senhor falou a Moisés e disse:"},
{v:12,t:"Quando fizeres o recenseamento dos filhos de Israel, cada um pagará ao Senhor o resgate da sua vida, para que não haja entre eles nenhuma praga por ocasião do recenseamento."},
{v:13,t:"Todo aquele que for recenseado dará meio siclo, segundo o siclo do santuário, que vale vinte gueras; meio siclo será a oferta para o Senhor."},
{v:14,t:"Todo aquele que for recenseado, de vinte anos para cima, dará essa oferta ao Senhor."},
{v:15,t:"O rico não dará mais, e o pobre não dará menos do que meio siclo, quando pagardes ao Senhor o resgate das vossas vidas.",n:"Diante de Deus, todas as vidas têm o mesmo preço."},
{v:16,t:"Receberás dos filhos de Israel esse dinheiro do resgate e o destinarás ao serviço da tenda do encontro; ele será para os filhos de Israel um memorial diante do Senhor, para o resgate das vossas vidas.",n:"Mais tarde, esta oferta se tornou o imposto anual do templo (compare Mateus 17,24–27)."},
{s:"A bacia de bronze"},
{v:17,t:"O Senhor falou a Moisés e disse:"},
{v:18,t:"Farás também uma bacia de bronze, com a sua base de bronze, para as abluções; tu a porás entre a tenda do encontro e o altar e lhe porás água,"},
{v:19,t:"e Aarão e os seus filhos lavarão nela as mãos e os pés."},
{v:20,t:"Quando entrarem na tenda do encontro, se lavarão com água, para que não morram; e também quando se aproximarem do altar para oficiar, para queimar uma oferta ao Senhor.",np:1},
{v:21,t:"Lavarão as mãos e os pés, para que não morram: é uma lei perpétua para ele e para a sua descendência, de geração em geração."},
{s:"O óleo da unção e o incenso"},
{v:22,t:"O Senhor falou a Moisés"},
{v:23,t:"e disse: Toma aromas de primeira qualidade: quinhentos siclos de mirra escolhida; a metade, isto é, duzentos e cinquenta siclos, de cinamomo aromático; duzentos e cinquenta siclos de cálamo aromático;"},
{v:24,t:"quinhentos siclos de cássia, segundo o siclo do santuário; e um hin de azeite de oliva."},
{v:25,t:"Com isso farás o óleo da unção sagrada, um perfume composto segundo a arte do perfumista: será o óleo da unção sagrada."},
{v:26,t:"Com ele ungirás a tenda do encontro, a arca do Testemunho,"},
{v:27,t:"a mesa com todos os seus utensílios, o candelabro com os seus utensílios, o altar do incenso,"},
{v:28,t:"o altar dos holocaustos com todos os seus utensílios, e a bacia com a sua base."},
{v:29,t:"Assim os consagrarás, e eles serão santíssimos: tudo o que os tocar ficará consagrado.",np:1},
{v:30,t:"Ungirás também Aarão e os seus filhos e os consagrarás, para que exerçam o sacerdócio em minha honra.",np:1},
{v:31,t:"E dirás aos filhos de Israel: Este será para mim o óleo da unção sagrada, de geração em geração."},
{v:32,t:"Não será derramado sobre o corpo de nenhum homem, e não fareis outro óleo com a mesma composição: é sagrado e será sagrado para vós."},
{v:33,t:"Quem fizer um perfume semelhante ou puser dele sobre um estranho será eliminado do seu povo.",np:1},
{v:34,t:"O Senhor disse a Moisés: Toma aromas: estacte, ônica, gálbano aromático e incenso puro, em partes iguais,",np:1},
{v:35,t:"e com eles farás um incenso composto segundo a arte do perfumista, temperado com sal, puro e santo."},
{v:36,t:"Reduzirás uma parte dele a pó muito fino e o porás diante do Testemunho, na tenda do encontro, onde me encontrarei contigo: será para vós coisa santíssima."},
{v:37,t:"Não fareis para vós um incenso com a mesma composição: ele será para ti coisa sagrada, reservada ao Senhor."},
{v:38,t:"Quem fizer um semelhante para desfrutar do seu perfume será eliminado do seu povo."}
];

window.TEXTOS_SEED["exodo"][31] = [
{s:"Os artesãos do santuário"},
{v:1,t:"O Senhor falou a Moisés e disse:"},
{v:2,t:"Eis que chamei pelo nome Beseleel, filho de Uri, filho de Hur, da tribo de Judá,"},
{v:3,t:"e o enchi do espírito de Deus, de sabedoria, de inteligência e de conhecimento para toda espécie de trabalho,",n:"É a primeira vez que a Bíblia diz de alguém que está cheio do espírito de Deus: e é um artista."},
{v:4,t:"para conceber projetos e executá-los em ouro, em prata e em bronze,"},
{v:5,t:"para lapidar e engastar pedras, para entalhar madeira e fazer toda espécie de trabalho."},
{v:6,t:"Eu lhe dei como auxiliar Ooliab, filho de Aquisamec, da tribo de Dã, e pus sabedoria no coração de todos os artesãos hábeis, para que façam tudo o que te ordenei:"},
{v:7,t:"a tenda do encontro, a arca do Testemunho, o propiciatório que está sobre ela e todos os utensílios da tenda;"},
{v:8,t:"a mesa e os seus utensílios, o candelabro de ouro puro com todos os seus utensílios, o altar do incenso,"},
{v:9,t:"o altar dos holocaustos com todos os seus utensílios, a bacia com a sua base,"},
{v:10,t:"as vestes tecidas, as vestes sagradas do sacerdote Aarão e as vestes dos seus filhos, para exercerem o sacerdócio,"},
{v:11,t:"o óleo da unção e o incenso aromático para o santuário. Farão tudo conforme o que te ordenei."},
{s:"O sábado, sinal da aliança"},
{v:12,t:"O Senhor falou a Moisés e disse:"},
{v:13,t:"Dize aos filhos de Israel: Guardai os meus sábados, porque o sábado é um sinal entre mim e vós, de geração em geração, para que saibais que eu sou o Senhor, que vos santifico."},
{v:14,t:"Guardai o sábado, porque é santo para vós. Quem o profanar será morto; quem fizer nele algum trabalho será eliminado do meio do seu povo.",n:"Nota do tradutor: a pena é dura, e o texto não foi suavizado; ela mostra que o sábado era visto como o próprio sinal da aliança (31,13.16–17)."},
{v:15,t:"Durante seis dias se fará o trabalho, mas o sétimo dia é sábado, dia de repouso consagrado ao Senhor: todo aquele que fizer algum trabalho no dia de sábado será morto.",np:1},
{v:16,t:"Os filhos de Israel guardarão o sábado, celebrando-o de geração em geração: é uma aliança perpétua"},
{v:17,t:"entre mim e os filhos de Israel, um sinal para sempre; pois em seis dias o Senhor fez o céu e a terra, e no sétimo dia descansou e tomou fôlego."},
{v:18,t:"Quando terminou de falar com Moisés no monte Sinai, o Senhor lhe deu as duas tábuas do Testemunho, tábuas de pedra escritas pelo dedo de Deus.",np:1,n:"O dedo de Deus: Jesus usa a expressão a propósito dos seus milagres (Lucas 11,20); os Padres da Igreja viram nela uma imagem do Espírito Santo, que escreve a lei nos corações (compare 2 Coríntios 3,3)."}
];

window.TEXTOS_SEED["exodo"][32] = [
{s:"O bezerro de ouro"},
{v:1,t:"Vendo que Moisés demorava a descer da montanha, o povo se reuniu em torno de Aarão e lhe disse: Vamos, faze-nos deuses que vão à nossa frente, porque não sabemos o que aconteceu a esse Moisés, o homem que nos tirou da terra do Egito."},
{v:2,t:"Aarão lhes disse: Tirai as argolas de ouro das orelhas das vossas mulheres, dos vossos filhos e das vossas filhas, e trazei-as a mim."},
{v:3,t:"Todo o povo fez o que ele tinha mandado e levou a Aarão as argolas."},
{v:4,t:"Ele as recebeu, deu forma ao ouro com o buril e fez dele um bezerro de metal fundido. E disseram: Estes são os teus deuses, Israel, que te tiraram da terra do Egito!",n:"O bezerro, ou touro jovem, era no Oriente símbolo de força e de fecundidade, às vezes pedestal de uma divindade invisível. Jeroboão repetirá o gesto em Betel e em Dã, com as mesmas palavras (1 Reis 12,28)."},
{v:5,t:"Vendo isso, Aarão construiu um altar diante do bezerro e mandou anunciar: Amanhã haverá uma festa em honra do Senhor.",n:"Aarão pretende honrar o Senhor com uma imagem: é justamente o que o mandamento proíbe (20,4–5)."},
{v:6,t:"No dia seguinte, levantaram-se de madrugada, ofereceram holocaustos e trouxeram sacrifícios de comunhão; o povo sentou-se para comer e beber, e depois se levantou para se divertir.",n:"São Paulo cita este versículo como advertência contra a idolatria (1 Coríntios 10,7)."},
{v:7,t:"O Senhor disse a Moisés: Vai, desce, porque o teu povo, que tiraste da terra do Egito, se corrompeu.",np:1},
{v:8,t:"Depressa se desviaram do caminho que eu lhes tinha ordenado: fizeram para si um bezerro de metal fundido, prostraram-se diante dele, ofereceram-lhe sacrifícios e disseram: Estes são os teus deuses, Israel, que te tiraram da terra do Egito!"},
{v:9,t:"E o Senhor disse ainda a Moisés: Vejo que este povo é um povo de cerviz dura;"},
{v:10,t:"deixa que a minha ira se inflame contra eles e que eu os destrua; e de ti farei uma grande nação.",n:"Deixa: Deus parece pedir licença a Moisés, como se a sua intercessão pudesse detê-lo; e é o que acontece."},
{v:11,t:"Moisés, porém, suplicou ao Senhor, seu Deus, e disse: Por que, Senhor, se inflama a tua ira contra o teu povo, que tiraste da terra do Egito com grande poder e mão forte?",np:1},
{v:12,t:"Que os egípcios não digam: Ele os tirou com astúcia, para matá-los nas montanhas e exterminá-los da face da terra. Que a tua ira se acalme, e sê indulgente com a maldade do teu povo."},
{v:13,t:"Lembra-te de Abraão, de Isaac e de Israel, teus servos, a quem juraste por ti mesmo, dizendo: Multiplicarei a vossa descendência como as estrelas do céu, e toda esta terra de que falei, eu a darei à vossa descendência, e vós a possuireis para sempre."},
{v:14,t:"O Senhor se aplacou e não fez o mal que tinha anunciado contra o seu povo."},
{s:"Moisés quebra as tábuas"},
{v:15,t:"Moisés voltou e desceu da montanha com as duas tábuas do Testemunho na mão, tábuas escritas dos dois lados"},
{v:16,t:"e feitas por Deus; a escrita era escrita de Deus, gravada nas tábuas."},
{v:17,t:"Josué ouviu o barulho do povo que gritava e disse a Moisés: Há um grito de guerra no acampamento."},
{v:18,l:["Moisés respondeu:","Não é grito de vitória,","nem grito de derrota;","o que eu ouço","são cantos."]},
{v:19,t:"Quando se aproximou do acampamento e viu o bezerro e as danças, Moisés se inflamou de ira, jogou das mãos as tábuas e as quebrou ao pé da montanha.",np:1,n:"Quebrar as tábuas é romper a aliança que o povo acabava de violar."},
{v:20,t:"Depois tomou o bezerro que tinham feito, queimou-o no fogo, triturou-o até reduzi-lo a pó, espalhou o pó na água e a deu de beber aos filhos de Israel."},
{v:21,t:"Moisés disse a Aarão: Que te fez este povo, para que o levasses a cometer um pecado tão grande?",np:1},
{v:22,t:"Aarão respondeu: Que o meu senhor não se irrite! Tu conheces este povo e sabes como é inclinado ao mal."},
{v:23,t:"Eles me disseram: Faze-nos deuses que vão à nossa frente, porque não sabemos o que aconteceu a esse Moisés, o homem que nos tirou da terra do Egito."},
{v:24,t:"Eu lhes disse: Quem tem ouro? E eles o tiraram e me deram; eu o joguei no fogo, e saiu este bezerro.",n:"A desculpa de Aarão é quase cômica: o bezerro teria saído sozinho do fogo."},
{v:25,t:"Moisés viu que o povo estava desenfreado, porque Aarão lhe tinha soltado as rédeas, para vergonha diante dos seus inimigos.",np:1},
{v:26,t:"Moisés se pôs à porta do acampamento e disse: Quem é do Senhor venha a mim! E todos os filhos de Levi se reuniram junto dele."},
{v:27,t:"Ele lhes disse: Assim diz o Senhor, o Deus de Israel: Cada um cinja a espada; passai e voltai pelo acampamento, de porta em porta, e cada um mate o seu irmão, o seu amigo e o seu vizinho.",n:"Nota do tradutor: um dos trechos mais duros da Bíblia, e o texto não foi suavizado. A narrativa explica por ele a vocação sacerdotal da tribo de Levi, fiel ao Senhor mesmo contra os próprios parentes (32,29; compare Deuteronômio 33,8–9)."},
{v:28,t:"Os filhos de Levi fizeram o que Moisés tinha dito, e naquele dia caíram do povo cerca de três mil homens."},
{v:29,t:"Moisés disse: Hoje vos consagrastes ao Senhor, cada um à custa do seu filho e do seu irmão, para que hoje ele vos dê a bênção.",n:"Vos consagrastes: à letra, enchestes as vossas mãos, a expressão da investidura sacerdotal (28,41)."},
{s:"A intercessão de Moisés"},
{v:30,t:"No dia seguinte, Moisés disse ao povo: Cometestes um grande pecado. Agora vou subir até o Senhor; talvez eu consiga obter o perdão do vosso pecado."},
{v:31,t:"Moisés voltou ao Senhor e disse: Ah! Este povo cometeu um grande pecado: fizeram para si deuses de ouro. Mas agora, ou perdoas o seu pecado,"},
{v:32,t:"ou, se não, apaga-me do livro que escreveste.",n:"Moisés prefere desaparecer com o povo a salvar-se sozinho. São Paulo dirá algo semelhante a respeito dos seus irmãos judeus (Romanos 9,3)."},
{v:33,t:"O Senhor respondeu a Moisés: É quem pecou contra mim que eu apagarei do meu livro."},
{v:34,t:"Agora vai, conduz o povo para onde eu te disse: o meu anjo irá à tua frente; mas, no dia do castigo, eu os castigarei também por este pecado."},
{v:35,t:"E o Senhor feriu o povo por causa do bezerro que Aarão tinha feito.",np:1}
];

window.TEXTOS_SEED["exodo"][33] = [
{s:"O Senhor não subirá com o povo"},
{v:1,t:"O Senhor disse a Moisés: Vai, sobe daqui, tu e o povo que tiraste da terra do Egito, para a terra que jurei a Abraão, a Isaac e a Jacó, dizendo: Eu a darei à tua descendência."},
{v:2,t:"Enviarei um anjo à tua frente e expulsarei os cananeus, os amorreus, os heteus, os ferezeus, os heveus e os jebuseus,"},
{v:3,t:"para que entres na terra onde corre leite e mel. Mas eu não subirei no meio de ti, porque és um povo de cerviz dura, para que eu não te extermine no caminho."},
{v:4,t:"Ao ouvir estas palavras duras, o povo ficou de luto, e ninguém pôs os seus enfeites.",np:1},
{v:5,t:"O Senhor disse a Moisés: Dize aos filhos de Israel: Tu és um povo de cerviz dura; se eu subisse um só instante no meio de ti, eu te exterminaria. Agora, pois, tira os teus enfeites, e eu verei o que farei contigo.",np:1},
{v:6,t:"E os filhos de Israel se despojaram dos seus enfeites desde o monte Horeb."},
{s:"A tenda do encontro"},
{v:7,t:"Moisés tomava a tenda e a armava fora do acampamento, longe dele, e a chamava tenda do encontro. Todo aquele que queria consultar o Senhor saía para a tenda do encontro, fora do acampamento.",n:"Esta tenda, fora do acampamento, é diferente do tabernáculo descrito nos capítulos 25–31: é uma tradição antiga sobre o lugar do encontro com Deus."},
{v:8,t:"Quando Moisés saía para a tenda, todo o povo se levantava; cada um ficava de pé à entrada da sua tenda e seguia Moisés com o olhar até que ele entrasse na tenda."},
{v:9,t:"Quando Moisés entrava na tenda, a coluna de nuvem descia e parava à entrada da tenda, e o Senhor falava com Moisés."},
{v:10,t:"Todo o povo via a coluna de nuvem parada à entrada da tenda; todos se levantavam e se prostravam, cada um à entrada da sua tenda."},
{v:11,t:"O Senhor falava com Moisés face a face, como um homem fala com o seu amigo. Depois Moisés voltava ao acampamento; mas o seu ajudante, o jovem Josué, filho de Nun, não se afastava da tenda.",n:"Face a face: expressão de intimidade, que não contradiz 33,20; Moisés fala com Deus como amigo, mas não vê o seu rosto."},
{s:"Moisés pede para ver a glória de Deus"},
{v:12,t:"Moisés disse ao Senhor: Tu me dizes: Faze subir este povo; mas não me revelaste quem vais enviar comigo. E, no entanto, disseste: Eu te conheço pelo nome, e achaste graça aos meus olhos."},
{v:13,t:"Agora, pois, se achei graça aos teus olhos, mostra-me o teu caminho, para que eu te conheça e continue a achar graça aos teus olhos; e lembra-te de que esta nação é o teu povo."},
{v:14,t:"O Senhor respondeu: A minha presença irá contigo, e eu te darei descanso."},
{v:15,t:"Moisés disse: Se tu mesmo não fores conosco, não nos faças sair daqui."},
{v:16,t:"Como se saberá que eu e o teu povo achamos graça aos teus olhos, senão caminhando tu conosco, para que sejamos distinguidos, eu e o teu povo, entre todos os povos que há sobre a terra?"},
{v:17,t:"O Senhor disse a Moisés: Também farei isso que pediste, porque achaste graça aos meus olhos, e eu te conheço pelo nome.",np:1},
{v:18,t:"Moisés disse: Mostra-me a tua glória."},
{v:19,t:"O Senhor respondeu: Farei passar diante de ti toda a minha bondade e proclamarei diante de ti o nome do Senhor; e tenho compaixão de quem quero ter compaixão, e sou misericordioso com quem quero ser misericordioso.",n:"São Paulo cita a segunda parte do versículo em Romanos 9,15."},
{v:20,t:"E acrescentou: Não poderás ver o meu rosto, porque o homem não pode ver-me e continuar vivo."},
{v:21,t:"E o Senhor disse ainda: Eis aqui um lugar junto de mim: ficarás sobre a rocha;"},
{v:22,t:"e, quando a minha glória passar, eu te porei numa fenda da rocha e te cobrirei com a minha mão até que eu tenha passado;"},
{v:23,t:"depois retirarei a minha mão, e me verás pelas costas; mas o meu rosto não se pode ver.",n:"Nota do tradutor: a imagem é ousada, e o texto não foi suavizado. Deus só se deixa conhecer pelas marcas da sua passagem; São João dirá que o Filho único o deu a conhecer (João 1,18)."}
];

window.TEXTOS_SEED["exodo"][34] = [
{s:"As novas tábuas"},
{v:1,t:"O Senhor disse a Moisés: Talha duas tábuas de pedra como as primeiras, e eu escreverei nelas as palavras que estavam nas primeiras tábuas, que quebraste."},
{v:2,t:"Fica pronto de manhã; sobe de manhã ao monte Sinai e ali te apresentarás a mim, no cume da montanha."},
{v:3,t:"Ninguém suba contigo, e ninguém apareça em toda a montanha; nem ovelhas nem bois pastem diante dela."},
{v:4,t:"Moisés talhou duas tábuas de pedra como as primeiras; levantou-se de madrugada e subiu ao monte Sinai, como o Senhor lhe tinha ordenado, levando nas mãos as duas tábuas."},
{s:"O Senhor proclama o seu nome"},
{v:5,t:"O Senhor desceu na nuvem, ficou ali com Moisés e proclamou o nome do Senhor."},
{v:6,t:"O Senhor passou diante dele e proclamou: O Senhor, o Senhor, Deus misericordioso e clemente, lento para a ira, rico em amor e fidelidade,",n:"A fórmula mais citada do Antigo Testamento sobre quem é Deus; volta nos Salmos e nos profetas (Salmo 103,8; Joel 2,13; Jonas 4,2)."},
{v:7,t:"que conserva o seu amor por mil gerações, que perdoa a iniquidade, a transgressão e o pecado, mas não deixa nada impune, e castiga a iniquidade dos pais nos filhos e nos netos, até a terceira e a quarta geração."},
{v:8,t:"Moisés logo se inclinou até o chão e se prostrou,"},
{v:9,t:"e disse: Se achei graça aos teus olhos, Senhor, peço-te que caminhes no meio de nós. É um povo de cerviz dura, mas tu perdoarás as nossas iniquidades e os nossos pecados e farás de nós a tua herança."},
{s:"A renovação da aliança"},
{v:10,t:"O Senhor disse: Eis que faço uma aliança diante de todo o teu povo: realizarei maravilhas como nunca se fizeram em toda a terra nem em nação alguma, e todo o povo no meio do qual estás verá a obra do Senhor, pois é terrível o que vou fazer contigo."},
{v:11,t:"Observa o que hoje te ordeno: eu expulsarei da tua frente os amorreus, os cananeus, os heteus, os ferezeus, os heveus e os jebuseus.",np:1},
{v:12,t:"Guarda-te de fazer aliança com os habitantes da terra em que vais entrar, para que não se tornem uma armadilha no meio de ti;"},
{v:13,t:"ao contrário, derrubareis os seus altares, quebrareis as suas estelas e cortareis os seus postes sagrados."},
{v:14,t:"Não te prostrarás diante de outro deus, porque o Senhor se chama Zeloso: é um Deus zeloso.",np:1},
{v:15,t:"Não faças aliança com os habitantes daquela terra, para que não aconteça que, quando se prostituírem com os seus deuses e lhes oferecerem sacrifícios, alguém te convide e comas das suas vítimas;",np:1,n:"Prostituir-se: imagem profética da infidelidade ao Senhor, comparada ao adultério (compare Oseias 2)."},
{v:16,t:"e não tomes as filhas deles como mulheres para os teus filhos, para que, prostituindo-se com os seus deuses, não levem também os teus filhos a se prostituírem com eles."},
{v:17,t:"Não farás para ti deuses de metal fundido.",np:1},
{v:18,t:"Observarás a festa dos Ázimos: durante sete dias comerás pães sem fermento, como te ordenei, no tempo marcado do mês de Abib; pois foi no mês da primavera que saíste do Egito.",np:1},
{v:19,t:"Todo o que abre o seio materno me pertence, todo macho do teu rebanho, tanto dos bois como das ovelhas.",np:1},
{v:20,t:"Resgatarás com um cordeiro o primeiro filhote da jumenta; se não o resgatares, tu lhe quebrarás a nuca. Resgatarás todo primogênito dos teus filhos. E ninguém se apresentará diante de mim de mãos vazias."},
{v:21,t:"Durante seis dias trabalharás, mas no sétimo dia descansarás, mesmo no tempo da lavoura e da colheita.",np:1},
{v:22,t:"Celebrarás a festa das Semanas, das primícias da colheita do trigo, e a festa da Recolha, na virada do ano.",np:1},
{v:23,t:"Três vezes por ano, todos os teus homens se apresentarão diante do Senhor Todo-Poderoso, o Deus de Israel.",np:1},
{v:24,t:"Pois expulsarei as nações da tua frente e alargarei as tuas fronteiras, e ninguém cobiçará a tua terra quando subires para te apresentar diante do Senhor, teu Deus, três vezes por ano."},
{v:25,t:"Não oferecerás o sangue do meu sacrifício com pão fermentado, e não ficará nada da vítima da festa da Páscoa até a manhã seguinte.",np:1},
{v:26,t:"Levarás à casa do Senhor, teu Deus, as primícias dos frutos da tua terra. Não cozinharás o cabrito no leite da sua mãe.",np:1},
{v:27,t:"O Senhor disse a Moisés: Escreve estas palavras, porque é segundo estas palavras que faço aliança contigo e com Israel.",np:1},
{v:28,t:"Moisés ficou ali com o Senhor quarenta dias e quarenta noites, sem comer pão nem beber água; e escreveu nas tábuas as palavras da aliança, as dez palavras.",np:1,n:"Quarenta dias e quarenta noites: como Elias a caminho do Horeb (1 Reis 19,8) e Jesus no deserto (Mateus 4,2)."},
{s:"O rosto radiante de Moisés"},
{v:29,t:"Quando Moisés desceu do monte Sinai, com as duas tábuas do Testemunho nas mãos, não sabia que a pele do seu rosto resplandecia, por ter falado com o Senhor.",n:"Resplandecia: o verbo hebraico, que vem de qeren, chifre, e também raio de luz, levou a antiga Vulgata a dizer que o rosto de Moisés tinha chifres, e assim o esculpiu Michelangelo; a Nova Vulgata corrigiu. São Paulo comenta este episódio em 2 Coríntios 3,7–18."},
{v:30,t:"Aarão e todos os filhos de Israel viram que a pele do rosto de Moisés resplandecia e tiveram medo de se aproximar dele;",np:1},
{v:31,t:"mas Moisés os chamou, e Aarão e todos os chefes da comunidade voltaram a ele; e Moisés falou com eles."},
{v:32,t:"Depois todos os filhos de Israel se aproximaram, e ele lhes transmitiu todas as ordens que o Senhor lhe tinha dado no monte Sinai."},
{v:33,t:"Quando Moisés acabou de falar com eles, pôs um véu sobre o rosto.",np:1},
{v:34,t:"Quando entrava diante do Senhor para falar com ele, tirava o véu até sair; e, ao sair, transmitia aos filhos de Israel o que lhe tinha sido ordenado."},
{v:35,t:"Os filhos de Israel viam que a pele do rosto de Moisés resplandecia; e Moisés voltava a pôr o véu sobre o rosto até entrar de novo para falar com o Senhor."}
];

window.TEXTOS_SEED["exodo"][35] = [
{s:"O sábado"},
{v:1,t:"Moisés reuniu toda a comunidade dos filhos de Israel e lhes disse: Eis o que o Senhor ordenou que se fizesse:"},
{v:2,t:"durante seis dias se fará o trabalho, mas o sétimo dia será para vós um dia santo, sábado de repouso consagrado ao Senhor: quem nele fizer algum trabalho será morto."},
{v:3,t:"Não acendereis fogo em nenhuma das vossas moradas no dia de sábado.",np:1},
{s:"As ofertas para o santuário"},
{v:4,t:"Moisés disse a toda a comunidade dos filhos de Israel: Eis o que o Senhor ordenou:"},
{v:5,t:"Separai do que tendes uma oferta para o Senhor. Todo aquele que tiver o coração generoso traga a sua oferta ao Senhor: ouro, prata e bronze;"},
{v:6,t:"púrpura violeta, púrpura escarlate, carmesim, linho fino e pelo de cabra;"},
{v:7,t:"peles de carneiro tingidas de vermelho, peles finas e madeira de acácia;"},
{v:8,t:"azeite para a iluminação, aromas para o óleo da unção e para o incenso perfumado;"},
{v:9,t:"pedras de ônix e outras pedras para engastar no efod e no peitoral."},
{v:10,t:"Venham todos os artesãos hábeis que há entre vós e façam tudo o que o Senhor ordenou:",np:1},
{v:11,t:"o tabernáculo, a sua tenda e a sua cobertura, os seus colchetes e as suas tábuas, as suas travessas, as suas colunas e as suas bases;"},
{v:12,t:"a arca e os seus varais, o propiciatório e o véu que o encobre;"},
{v:13,t:"a mesa, os seus varais e todos os seus utensílios, e os pães da proposição;"},
{v:14,t:"o candelabro para a iluminação, os seus utensílios, as suas lâmpadas e o azeite para a iluminação;"},
{v:15,t:"o altar do incenso e os seus varais, o óleo da unção e o incenso aromático; a cortina da entrada do tabernáculo;"},
{v:16,t:"o altar dos holocaustos com a sua grelha de bronze, os seus varais e todos os seus utensílios; a bacia e a sua base;"},
{v:17,t:"as cortinas do átrio, as suas colunas e as suas bases, e a cortina da entrada do átrio;"},
{v:18,t:"as estacas do tabernáculo e as estacas do átrio, com as suas cordas;"},
{v:19,t:"as vestes tecidas para o serviço no santuário, as vestes sagradas do sacerdote Aarão e as vestes dos seus filhos, para exercerem o sacerdócio."},
{s:"A generosidade do povo"},
{v:20,t:"Então toda a comunidade dos filhos de Israel saiu da presença de Moisés;"},
{v:21,t:"e todos os que tinham o coração generoso e o espírito disposto vieram trazer a sua oferta ao Senhor, para a obra da tenda do encontro, para todo o seu serviço e para as vestes sagradas."},
{v:22,t:"Vieram homens e mulheres, todos os de coração generoso, trazendo broches, brincos, anéis e pulseiras, toda espécie de objetos de ouro; cada um apresentou ao Senhor uma oferta de ouro."},
{v:23,t:"Todos os que tinham púrpura violeta, púrpura escarlate, carmesim, linho fino, pelo de cabra, peles de carneiro tingidas de vermelho e peles finas,"},
{v:24,t:"prata ou bronze, os trouxeram como oferta ao Senhor, e também madeira de acácia para os vários trabalhos."},
{v:25,t:"As mulheres hábeis trouxeram o que tinham fiado: púrpura violeta, púrpura escarlate, carmesim e linho fino",np:1},
{v:26,t:"e pelo de cabra, dando tudo de boa vontade."},
{v:27,t:"Os chefes trouxeram as pedras de ônix e as outras pedras para engastar no efod e no peitoral,",np:1},
{v:28,t:"os aromas e o azeite para a iluminação, para o óleo da unção e para o incenso perfumado."},
{v:29,t:"Todos os homens e mulheres de coração generoso trouxeram ofertas para toda a obra que o Senhor tinha ordenado por meio de Moisés; os filhos de Israel trouxeram ao Senhor ofertas voluntárias."},
{s:"Beseleel e Ooliab"},
{v:30,t:"Moisés disse aos filhos de Israel: Vede, o Senhor chamou pelo nome Beseleel, filho de Uri, filho de Hur, da tribo de Judá,"},
{v:31,t:"e o encheu do espírito de Deus, de sabedoria, de inteligência e de conhecimento para toda espécie de trabalho,"},
{v:32,t:"para conceber projetos e executá-los em ouro, em prata e em bronze,"},
{v:33,t:"para lapidar e engastar pedras, para entalhar madeira e realizar toda espécie de obra de arte."},
{v:34,t:"Deu-lhe também o dom de ensinar, a ele e a Ooliab, filho de Aquisamec, da tribo de Dã."},
{v:35,t:"Encheu-os de sabedoria para executar toda espécie de trabalho de artesão, de desenhista e de bordador em púrpura violeta, púrpura escarlate, carmesim e linho fino, e de tecelão; são capazes de realizar toda espécie de obra e de inventar projetos."}
];

window.TEXTOS_SEED["exodo"][36] = [
{s:"O povo traz mais do que o necessário"},
{v:1,t:"Beseleel, Ooliab e todos os artesãos hábeis, a quem o Senhor tinha dado sabedoria e inteligência para saberem executar os trabalhos necessários ao serviço do santuário, fizeram tudo conforme o Senhor tinha ordenado."},
{v:2,t:"Moisés chamou Beseleel, Ooliab e todos os artesãos hábeis, a quem o Senhor tinha dado sabedoria, todos os que se ofereciam de boa vontade para realizar a obra,",np:1},
{v:3,t:"e eles receberam de Moisés todas as ofertas que os filhos de Israel tinham trazido para a obra do serviço do santuário. Mas o povo continuava a trazer-lhe ofertas voluntárias todas as manhãs."},
{v:4,t:"Então todos os artesãos que faziam a obra do santuário deixaram cada um o trabalho que estava fazendo"},
{v:5,t:"e disseram a Moisés: O povo traz mais do que é necessário para a obra que o Senhor mandou fazer."},
{v:6,t:"Moisés mandou então proclamar no acampamento: Que nenhum homem e nenhuma mulher faça mais ofertas para o santuário! E o povo deixou de trazer ofertas,"},
{v:7,t:"porque o que tinham trazido bastava, e até sobrava, para toda a obra.",n:"Rara cena de generosidade que é preciso conter: o contrário do bezerro de ouro, feito também com as joias do povo (32,2–4)."},
{s:"A construção do tabernáculo"},
{v:8,t:"Todos os artesãos hábeis que trabalhavam na obra fizeram o tabernáculo com dez cortinas de linho fino retorcido, de púrpura violeta, de púrpura escarlate e de carmesim, com querubins bordados artisticamente.",n:"Os capítulos 36–39 repetem quase palavra por palavra as instruções dos capítulos 25–31: tudo é feito como o Senhor ordenou."},
{v:9,t:"Cada cortina tinha vinte e oito côvados de comprimento e quatro côvados de largura; todas as cortinas tinham a mesma medida."},
{v:10,t:"Uniu cinco cortinas uma à outra, e as outras cinco também uniu uma à outra."},
{v:11,t:"Fez laços de púrpura violeta na borda da última cortina do primeiro conjunto, e fez o mesmo na borda da última cortina do segundo conjunto."},
{v:12,t:"Fez cinquenta laços numa cortina e cinquenta laços na borda da cortina do segundo conjunto, de modo que os laços ficassem um diante do outro."},
{v:13,t:"Fez também cinquenta colchetes de ouro e com eles uniu as cortinas uma à outra, de modo que o tabernáculo formou um todo."},
{v:14,t:"Fez também onze cortinas de pelo de cabra, para servirem de tenda sobre o tabernáculo."},
{v:15,t:"Cada cortina tinha trinta côvados de comprimento e quatro côvados de largura; as onze cortinas tinham a mesma medida."},
{v:16,t:"Uniu cinco cortinas à parte e seis cortinas à parte."},
{v:17,t:"Fez cinquenta laços na borda da última cortina do primeiro conjunto e cinquenta laços na borda da cortina do segundo conjunto, para uni-las;",np:1},
{v:18,t:"e fez cinquenta colchetes de bronze, para unir a tenda, de modo que formasse um todo."},
{v:19,t:"Fez também para a tenda uma cobertura de peles de carneiro tingidas de vermelho e, por cima dela, outra cobertura de peles finas."},
{v:20,t:"Fez para o tabernáculo tábuas de madeira de acácia, postas de pé.",np:1},
{v:21,t:"Cada tábua tinha dez côvados de comprimento e um côvado e meio de largura."},
{v:22,t:"Cada tábua tinha dois encaixes, para se unir à outra; assim fez com todas as tábuas do tabernáculo.",np:1},
{v:23,t:"Fez as tábuas do tabernáculo: vinte tábuas para o lado sul, voltado para o meio-dia,"},
{v:24,t:"e fez quarenta bases de prata para as vinte tábuas, duas bases debaixo de cada tábua, para os seus dois encaixes."},
{v:25,t:"Para o outro lado do tabernáculo, o lado norte, fez vinte tábuas,"},
{v:26,t:"com as suas quarenta bases de prata, duas bases debaixo de cada tábua."},
{v:27,t:"Para o fundo do tabernáculo, do lado do ocidente, fez seis tábuas,"},
{v:28,t:"e fez duas tábuas para os cantos do fundo do tabernáculo;"},
{v:29,t:"elas eram duplas desde baixo até em cima, unidas por uma só argola. Assim fez com as duas tábuas dos dois cantos,"},
{v:30,t:"de modo que eram oito tábuas com as suas bases de prata, dezesseis bases, duas debaixo de cada tábua."},
{v:31,t:"Fez também travessas de madeira de acácia: cinco para as tábuas de um lado do tabernáculo,"},
{v:32,t:"cinco para as tábuas do outro lado do tabernáculo e cinco para as tábuas do fundo do tabernáculo, do lado do ocidente."},
{v:33,t:"Fez a travessa do meio, que passava pelo meio das tábuas, de uma extremidade à outra."},
{v:34,t:"Revestiu de ouro as tábuas e fez de ouro as argolas por onde passavam as travessas; e revestiu de ouro também as travessas."},
{v:35,t:"Fez o véu de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido, com querubins bordados artisticamente;",np:1},
{v:36,t:"e fez para ele quatro colunas de acácia, que revestiu de ouro, com ganchos de ouro, e fundiu para elas quatro bases de prata."},
{v:37,t:"Fez para a entrada da tenda uma cortina de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido, obra de bordador,",np:1},
{v:38,t:"e cinco colunas com os seus ganchos; revestiu de ouro os seus capitéis e as suas vergas, e as suas cinco bases eram de bronze."}
];

window.TEXTOS_SEED["exodo"][37] = [
{s:"A arca e o propiciatório"},
{v:1,t:"Beseleel fez a arca de madeira de acácia, de dois côvados e meio de comprimento, um côvado e meio de largura e um côvado e meio de altura; e a revestiu de ouro puro por dentro e por fora."},
{v:2,t:"Fez ao redor dela uma moldura de ouro,",np:1},
{v:3,t:"e fundiu para ela quatro argolas de ouro, para os seus quatro pés: duas argolas de um lado e duas do outro."},
{v:4,t:"Fez também varais de madeira de acácia, que revestiu de ouro,"},
{v:5,t:"e os passou pelas argolas dos lados da arca, para transportá-la."},
{v:6,t:"Fez o propiciatório de ouro puro, de dois côvados e meio de comprimento e um côvado e meio de largura.",np:1},
{v:7,t:"Fez também dois querubins de ouro batido, nas duas extremidades do propiciatório:"},
{v:8,t:"um querubim numa extremidade e o outro na outra; fez os querubins formando uma só peça com o propiciatório, nas suas duas extremidades."},
{v:9,t:"Os querubins tinham as asas estendidas para o alto e cobriam com elas o propiciatório; estavam voltados um para o outro, com o rosto voltado para o propiciatório."},
{s:"A mesa"},
{v:10,t:"Fez a mesa de madeira de acácia, de dois côvados de comprimento, um côvado de largura e um côvado e meio de altura;"},
{v:11,t:"revestiu-a de ouro puro e fez ao redor dela uma moldura de ouro."},
{v:12,t:"Fez também ao redor dela um friso de quatro dedos de largura e, sobre o friso, uma moldura de ouro.",np:1},
{v:13,t:"Fundiu para ela quatro argolas de ouro e as pôs nos quatro cantos, junto aos quatro pés da mesa,"},
{v:14,t:"perto do friso; e passou por elas os varais, para transportar a mesa."},
{v:15,t:"Fez os varais de madeira de acácia e os revestiu de ouro;"},
{v:16,t:"e fez de ouro puro os utensílios da mesa: os pratos, as taças, as bacias e as jarras para as libações."},
{s:"O candelabro"},
{v:17,t:"Fez o candelabro de ouro puro, trabalhado a martelo, a base e a haste; os seus cálices, os seus botões e as suas flores formavam uma só peça com ele."},
{v:18,t:"Seis braços saíam dos seus lados: três braços de um lado e três do outro."},
{v:19,t:"Num braço havia três cálices em forma de flor de amendoeira, com botão e flor; e no outro braço, três cálices em forma de flor de amendoeira, com botão e flor; assim eram os seis braços que saíam do candelabro."},
{v:20,t:"Na própria haste havia quatro cálices em forma de flor de amendoeira, com os seus botões e as suas flores:"},
{v:21,t:"um botão debaixo de cada par de braços, nos três pares de braços que saíam da haste."},
{v:22,t:"Os botões e os braços formavam uma só peça com o candelabro: tudo de ouro puro, trabalhado a martelo."},
{v:23,t:"Fez também as suas sete lâmpadas, as suas tesouras de pavio e os seus pratinhos, de ouro puro."},
{v:24,t:"O candelabro, com todos os seus utensílios, pesava um talento de ouro puro."},
{s:"O altar do incenso"},
{v:25,t:"Fez o altar do incenso de madeira de acácia, de um côvado de comprimento e um côvado de largura: era quadrado; e tinha dois côvados de altura; os seus chifres formavam uma só peça com ele."},
{v:26,t:"Revestiu-o de ouro puro, a parte de cima, os lados ao redor e os chifres;"},
{v:27,t:"fez ao redor dele uma moldura de ouro e duas argolas de ouro debaixo da moldura, dos dois lados, para nelas passarem os varais com que seria transportado."},
{v:28,t:"Fez os varais de madeira de acácia e os revestiu de ouro."},
{v:29,t:"Preparou também o óleo da unção sagrada e o incenso puro e aromático, segundo a arte do perfumista.",np:1}
];

window.TEXTOS_SEED["exodo"][38] = [
{s:"O altar dos holocaustos e a bacia"},
{v:1,t:"Fez o altar dos holocaustos de madeira de acácia, de cinco côvados de comprimento e cinco côvados de largura: era quadrado; e tinha três côvados de altura."},
{v:2,t:"Nos seus quatro cantos fez chifres, que formavam uma só peça com ele, e o revestiu de bronze."},
{v:3,t:"Fez também de bronze todos os utensílios do altar: os recipientes para as cinzas, as pás, as bacias, os garfos e os braseiros."},
{v:4,t:"Fez para o altar uma grelha de bronze em forma de rede, debaixo da borda, de baixo até a metade da altura do altar,"},
{v:5,t:"e fundiu quatro argolas nos quatro cantos da grelha de bronze, para nelas passarem os varais."},
{v:6,t:"Fez os varais de madeira de acácia e os revestiu de bronze,"},
{v:7,t:"e os passou pelas argolas, nos lados do altar, para transportá-lo. Fez o altar oco, de tábuas."},
{v:8,t:"Fez também a bacia de bronze, com a sua base de bronze, com os espelhos das mulheres que serviam à entrada da tenda do encontro.",np:1,n:"Os espelhos eram de bronze polido. Estas mulheres que serviam à entrada da tenda voltam a aparecer em 1 Samuel 2,22."},
{s:"O átrio"},
{v:9,t:"Fez o átrio. Do lado sul, voltado para o meio-dia, as cortinas do átrio eram de linho fino retorcido, num comprimento de cem côvados,"},
{v:10,t:"com vinte colunas e as suas vinte bases de bronze; os ganchos das colunas e as suas vergas eram de prata."},
{v:11,t:"Do lado norte, as cortinas, as colunas, as bases, os ganchos e as vergas das colunas eram da mesma medida, do mesmo trabalho e do mesmo metal."},
{v:12,t:"Do lado do ocidente, havia cortinas num comprimento de cinquenta côvados, com dez colunas e as suas dez bases; os ganchos das colunas e as suas vergas eram de prata."},
{v:13,t:"Do lado do oriente, a largura era de cinquenta côvados:"},
{v:14,t:"de um lado havia quinze côvados de cortinas, com três colunas e três bases;"},
{v:15,t:"e do outro lado, já que entre os dois lados ficava a entrada do átrio, também quinze côvados de cortinas, com três colunas e três bases."},
{v:16,t:"Todas as cortinas ao redor do átrio eram de linho fino retorcido."},
{v:17,t:"As bases das colunas eram de bronze; os ganchos das colunas e as suas vergas eram de prata, e os seus capitéis eram revestidos de prata; todas as colunas do átrio eram ligadas por vergas de prata."},
{v:18,t:"A cortina da entrada do átrio era obra de bordador, de púrpura violeta, de púrpura escarlate, de carmesim e de linho fino retorcido; tinha vinte côvados de comprimento e cinco côvados de altura, como as cortinas do átrio."},
{v:19,t:"As suas colunas eram quatro, com as suas quatro bases de bronze; os seus ganchos eram de prata, e os seus capitéis e as suas vergas eram revestidos de prata.",np:1},
{v:20,t:"Todas as estacas do tabernáculo e do átrio ao redor eram de bronze."},
{s:"As contas do santuário"},
{v:21,t:"Estas são as contas do tabernáculo, o tabernáculo do Testemunho, feitas por ordem de Moisés, pelo serviço dos levitas, sob a direção de Itamar, filho do sacerdote Aarão."},
{v:22,t:"Beseleel, filho de Uri, filho de Hur, da tribo de Judá, fez tudo o que o Senhor tinha ordenado a Moisés;"},
{v:23,t:"e com ele esteve Ooliab, filho de Aquisamec, da tribo de Dã, artesão, desenhista e bordador em púrpura violeta, púrpura escarlate, carmesim e linho fino."},
{v:24,t:"Todo o ouro empregado na obra do santuário, o ouro das ofertas, foi de vinte e nove talentos e setecentos e trinta siclos, segundo o siclo do santuário.",np:1},
{v:25,t:"A prata dos recenseados da comunidade foi de cem talentos e mil setecentos e setenta e cinco siclos, segundo o siclo do santuário:"},
{v:26,t:"um beca por pessoa, isto é, meio siclo, segundo o siclo do santuário, de todos os recenseados de vinte anos para cima, isto é, de seiscentos e três mil quinhentos e cinquenta homens.",n:"Beca: meio siclo, como explica o próprio texto (compare 30,13–15)."},
{v:27,t:"Os cem talentos de prata serviram para fundir as bases do santuário e as bases do véu: cem bases para cem talentos, um talento por base."},
{v:28,t:"Com os mil setecentos e setenta e cinco siclos fez os ganchos das colunas, revestiu os seus capitéis e as ligou com vergas."},
{v:29,t:"O bronze das ofertas foi de setenta talentos e dois mil e quatrocentos siclos;"},
{v:30,t:"com ele fez as bases da entrada da tenda do encontro, o altar de bronze com a sua grelha e todos os utensílios do altar,"},
{v:31,t:"as bases ao redor do átrio e as bases da entrada do átrio, todas as estacas do tabernáculo e todas as estacas ao redor do átrio."}
];
